import { createBrowserClient } from "@supabase/ssr";

import { getPublicEnv } from "@/lib/env";

/** Cliente Supabase para Client Components. */
export function createClient() {
  const env = getPublicEnv();
  return createBrowserClient(
    env.NEXT_PUBLIC_SUPABASE_URL,
    env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
  );
}
import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";

import { getPublicEnv } from "@/lib/env";

/**
 * Renova a sessão do Supabase a cada requisição e devolve a resposta com os
 * cookies atualizados, junto com o usuário autenticado (ou `null`).
 * Pensado para ser chamado a partir de `src/proxy.ts`.
 */
export async function updateSession(request: NextRequest) {
  let response = NextResponse.next({ request });
  const env = getPublicEnv();

  const supabase = createServerClient(
    env.NEXT_PUBLIC_SUPABASE_URL,
    env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          for (const { name, value } of cookiesToSet) {
            request.cookies.set(name, value);
          }
          response = NextResponse.next({ request });
          for (const { name, value, options } of cookiesToSet) {
            response.cookies.set(name, value, options);
          }
        },
      },
    },
  );

  // Não coloque código entre a criação do cliente e getUser(): isso pode
  // causar logouts aleatórios difíceis de depurar.
  const {
    data: { user },
  } = await supabase.auth.getUser();

  return { response, user };
}
import "server-only";

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";

import { getPublicEnv } from "@/lib/env";

/** Cliente Supabase para Server Components, Server Actions e Route Handlers. */
export async function createClient() {
  const cookieStore = await cookies();
  const env = getPublicEnv();

  return createServerClient(
    env.NEXT_PUBLIC_SUPABASE_URL,
    env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            for (const { name, value, options } of cookiesToSet) {
              cookieStore.set(name, value, options);
            }
          } catch {
            // Chamado a partir de um Server Component, onde cookies são somente leitura.
            // O proxy renova a sessão, então pode ser ignorado com segurança.
          }
        },
      },
    },
  );
}
import { z } from "zod";

const publicSchema = z.object({
  NEXT_PUBLIC_SUPABASE_URL: z.url(),
  NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: z.string().min(1),
});

const serverSchema = publicSchema.extend({
  TMDB_READ_TOKEN: z.string().min(1),
});

export type PublicEnv = z.infer<typeof publicSchema>;
export type ServerEnv = z.infer<typeof serverSchema>;

export class EnvError extends Error {
  constructor(public readonly variables: string[]) {
    super(
      `Variáveis de ambiente ausentes ou inválidas: ${variables.join(", ")}. ` +
        "Confira o arquivo .env.local (veja .env.example).",
    );
    this.name = "EnvError";
  }
}

function parse<T extends z.ZodType>(schema: T, source: Record<string, string | undefined>) {
  const result = schema.safeParse(source);
  if (!result.success) {
    const variables = [...new Set(result.error.issues.map((issue) => String(issue.path[0])))];
    throw new EnvError(variables);
  }
  return result.data as z.infer<T>;
}

export function parsePublicEnv(source: Record<string, string | undefined>): PublicEnv {
  return parse(publicSchema, source);
}

export function parseServerEnv(source: Record<string, string | undefined>): ServerEnv {
  return parse(serverSchema, source);
}

let cachedPublicEnv: PublicEnv | undefined;

/**
 * Variáveis seguras para o navegador. As referências a `process.env.NEXT_PUBLIC_*`
 * precisam ser literais para o Next.js conseguir embuti-las no bundle do cliente.
 */
export function getPublicEnv(): PublicEnv {
  cachedPublicEnv ??= parsePublicEnv({
    NEXT_PUBLIC_SUPABASE_URL: process.env.NEXT_PUBLIC_SUPABASE_URL,
    NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
  });
  return cachedPublicEnv;
}
export default function HomePage() {
  return (
    <section className="mx-auto flex max-w-3xl flex-1 flex-col items-center justify-center gap-6 px-4 py-24 text-center">
      <h1 className="text-4xl font-bold tracking-tight sm:text-6xl">
        Filme <span className="text-primary">Certo</span>
      </h1>
      <p className="text-muted-foreground max-w-xl text-lg">
        Conte do que você gosta e receba recomendações de filmes feitas para o seu gosto, com onde
        assistir no Brasil.
      </p>
    </section>
  );
}
import Link from "next/link";

export function Header() {
  return (
    <header className="border-border/60 bg-background/80 sticky top-0 z-40 border-b backdrop-blur">
      <div className="mx-auto flex h-16 max-w-6xl items-center justify-between px-4">
        <Link href="/" className="text-xl font-bold tracking-tight">
          Filme <span className="text-primary">Certo</span>
        </Link>
        <nav aria-label="Navegação principal" className="text-muted-foreground text-sm">
          <Link href="/sobre" className="hover:text-foreground transition-colors">
            Sobre
          </Link>
        </nav>
      </div>
    </header>
  );
}
