}

/** Estado devolvido pelas Server Actions de auth para `useActionState`. */
export type EstadoFormulario<Campo extends string> = {
  /** Erro por campo, já em pt-BR. */
  erros?: Partial<Record<Campo, string>>;
  /** Erro geral do formulário (ex.: credenciais inválidas). */
  mensagem?: string;
  /** Valores para reexibir no formulário; senhas nunca voltam. */
  valores?: Partial<Record<Campo, string>>;
};

export type CampoLogin = "email" | "senha";
export type CampoCadastro = "nome" | "email" | "senha" | "confirmacao";

"use server";

import { redirect } from "next/navigation";
import type { z } from "zod";

import { traduzirErroAuth } from "@/features/auth/erros";
import type { CampoCadastro, CampoLogin, EstadoFormulario } from "@/features/auth/estado";
import { sanitizarNext } from "@/features/auth/redirecionamento";
import { cadastroSchema, loginSchema } from "@/features/auth/schema";
import { createClient } from "@/lib/supabase/server";

function texto(formData: FormData, campo: string): string {
  const valor = formData.get(campo);
  return typeof valor === "string" ? valor : "";
}

function primeiroErroPorCampo<Campo extends string>(erro: z.ZodError) {
  const erros: Partial<Record<Campo, string>> = {};
  for (const issue of erro.issues) {
    const campo = issue.path[0] as Campo;
    erros[campo] ??= issue.message;
  }
  return erros;
}

export async function entrar(
  _anterior: EstadoFormulario<CampoLogin>,
  formData: FormData,
): Promise<EstadoFormulario<CampoLogin>> {
  const valores = { email: texto(formData, "email") };
  const resultado = loginSchema.safeParse({ ...valores, senha: texto(formData, "senha") });
  if (!resultado.success) {
    return { erros: primeiroErroPorCampo(resultado.error), valores };
  }

  const supabase = await createClient();
  const { error } = await supabase.auth.signInWithPassword({
    email: resultado.data.email,
    password: resultado.data.senha,
  });
  if (error) {
    if (error.code !== "invalid_credentials") {
      console.error("[auth] falha no login:", error.code, error.message);
    }
    return { mensagem: traduzirErroAuth(error.code), valores };
  }

  redirect(sanitizarNext(texto(formData, "next")));
}

export async function cadastrar(
  _anterior: EstadoFormulario<CampoCadastro>,
  formData: FormData,
): Promise<EstadoFormulario<CampoCadastro>> {
  const valores = { nome: texto(formData, "nome"), email: texto(formData, "email") };
  const resultado = cadastroSchema.safeParse({
    ...valores,
    senha: texto(formData, "senha"),
    confirmacao: texto(formData, "confirmacao"),
  });
  if (!resultado.success) {
    return { erros: primeiroErroPorCampo(resultado.error), valores };
  }

  const supabase = await createClient();
  const { error } = await supabase.auth.signUp({
    email: resultado.data.email,
    password: resultado.data.senha,
    options: { data: { nome: resultado.data.nome } },
  });
  if (error) {
    console.error("[auth] falha no cadastro:", error.code, error.message);
    return { mensagem: traduzirErroAuth(error.code), valores };
  }

  redirect("/dashboard");
}

export async function sair(): Promise<void> {
  const supabase = await createClient();
  await supabase.auth.signOut();
  redirect("/");
}

import { NextResponse, type NextRequest } from "next/server";

import { DESTINO_PADRAO } from "@/features/auth/redirecionamento";
import { updateSession } from "@/lib/supabase/middleware";

/** Rotas da área logada (grupo `(app)`). */
const ROTAS_PROTEGIDAS = ["/dashboard"];
/** Rotas que só fazem sentido sem sessão. */
const ROTAS_DE_VISITANTE = ["/", "/login", "/cadastro"];

function corresponde(caminho: string, rotas: string[]) {
  return rotas.some((rota) => caminho === rota || caminho.startsWith(`${rota}/`));
}

/** Redireciona mantendo os cookies de sessão que o Supabase acabou de renovar. */
function redirecionar(destino: URL, response: NextResponse) {
  const redirect = NextResponse.redirect(destino);
  for (const cookie of response.cookies.getAll()) redirect.cookies.set(cookie);
  return redirect;
}

/**
 * Checagem otimista: renova a sessão e redireciona antes de renderizar.
 * A checagem definitiva fica no layout de `(app)` e na RLS do banco.
 */
export async function proxy(request: NextRequest) {
  const { response, user } = await updateSession(request);
  const { pathname, search } = request.nextUrl;

  if (!user && corresponde(pathname, ROTAS_PROTEGIDAS)) {
    const login = new URL("/login", request.url);
    login.searchParams.set("next", `${pathname}${search}`);
    return redirecionar(login, response);
  }

  if (user && ROTAS_DE_VISITANTE.includes(pathname)) {
    return redirecionar(new URL(DESTINO_PADRAO, request.url), response);
  }

  return response;
}

export const config = {
  matcher: ["/((?!api|_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)"],
};

