/** Ex.: "Ação, Drama · Médios (90 a 120 min) · Toda semana". */
export function resumirPreferencias({ generos, duracao, frequencia }: PreferenciasInput): string {
  const nomes = GENEROS.filter((genero) => generos.includes(genero.id)).map((g) => g.nome);
  return [nomes.join(", "), ROTULOS_DURACAO[duracao], ROTULOS_FREQUENCIA[frequencia]].join(" · ");
}

import "server-only";

import { cache } from "react";

import type { PreferenciasInput } from "@/features/preferencias/schema";
import { createClient } from "@/lib/supabase/server";

/** Preferências do usuário logado, ou `null` se ele ainda não fez o onboarding. */
export const obterPreferencias = cache(async (): Promise<PreferenciasInput | null> => {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("preferencias")
    .select("generos, duracao, frequencia")
    .maybeSingle();

  if (error) {
    console.error("[preferencias] falha ao ler:", error.code, error.message);
    throw new Error("Não foi possível carregar suas preferências.");
  }
  return data;
});

"use server";

import { redirect } from "next/navigation";

import { preferenciasSchema } from "@/features/preferencias/schema";
import { createClient } from "@/lib/supabase/server";

export type EstadoPreferencias = { mensagem?: string };

const ERRO_GENERICO = "Não foi possível salvar agora. Tente de novo.";

export async function salvarPreferencias(
  _anterior: EstadoPreferencias,
  formData: FormData,
): Promise<EstadoPreferencias> {
  const resultado = preferenciasSchema.safeParse({
    generos: formData.getAll("generos").map(Number),
    duracao: formData.get("duracao"),
    frequencia: formData.get("frequencia"),
  });
  if (!resultado.success) {
    return { mensagem: resultado.error.issues[0]?.message ?? ERRO_GENERICO };
  }

  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) redirect("/login?next=%2Fonboarding");

  const { error } = await supabase
    .from("preferencias")
    .upsert({ usuario_id: user.id, ...resultado.data });
  if (error) {
    console.error("[preferencias] falha ao salvar:", error.code, error.message);
    return { mensagem: ERRO_GENERICO };
  }

  redirect("/dashboard");
}

