    token: "t",
    baseUrl: "https://tmdb.falso/3",
    fetch: fetchFalso as unknown as typeof fetch,
    esperar: async () => {},
  });
  return { api: criarApiFilmes(cliente), fetchFalso };
}

function chamada(fetchFalso: ReturnType<typeof vi.fn>, indice = 0) {
