import "server-only";

import { getServerEnv } from "@/lib/env.server";

export class TmdbErro extends Error {
  constructor(
    message: string,
    /** Status HTTP, ou `null` para timeout, falha de rede ou formato inesperado. */
    public readonly status: number | null,
  ) {
    super(message);
    this.name = "TmdbErro";
  }
}

export type Parametros = Record<string, string | number | boolean | undefined>;

export type ClienteTmdb = {
  requisitar(caminho: string, parametros: Parametros, revalidate: number): Promise<unknown>;
};

type Opcoes = {
  token: string;
  baseUrl: string;
  fetch?: typeof fetch;
  /** Espera entre tentativas; injetável para os testes não dormirem. */
  esperar?: (ms: number) => Promise<void>;
  timeoutMs?: number;
};

const NOVAS_TENTATIVAS = 2;
const ESPERAS_MS = [500, 1000];
const RETRY_AFTER_MAX_MS = 5000;

const dormir = (ms: number) => new Promise<void>((resolver) => setTimeout(resolver, ms));

function deveRepetir(status: number) {
  return status === 429 || status >= 500;
}

function esperaRetryAfter(resposta: Response, padrao: number) {
  const segundos = Number(resposta.headers.get("Retry-After"));
  return Number.isFinite(segundos) && segundos > 0
    ? Math.min(segundos * 1000, RETRY_AFTER_MAX_MS)
    : padrao;
}

export function criarClienteTmdb({
  token,
  baseUrl,
  fetch: fetchImpl = fetch,
  esperar = dormir,
  timeoutMs = 8000,
}: Opcoes): ClienteTmdb {
  async function requisitar(caminho: string, parametros: Parametros, revalidate: number) {
    const url = new URL(`${baseUrl.replace(/\/$/, "")}${caminho}`);
    for (const [chave, valor] of Object.entries({ ...parametros, language: "pt-BR" })) {
      if (valor !== undefined) url.searchParams.set(chave, String(valor));
    }

    let ultimoErro = new TmdbErro("Falha ao consultar o TMDB", null);

    for (let tentativa = 0; tentativa <= NOVAS_TENTATIVAS; tentativa++) {
      const esperaPadrao = ESPERAS_MS[tentativa] ?? ESPERAS_MS.at(-1)!;
      let resposta: Response;
      try {
        resposta = await fetchImpl(url.toString(), {
          headers: { Authorization: `Bearer ${token}`, accept: "application/json" },
          signal: AbortSignal.timeout(timeoutMs),
          next: { revalidate },
        });
      } catch {
        // Timeout ou falha de rede: a mensagem original pode conter a URL, então não é repassada.
        ultimoErro = new TmdbErro("Sem resposta do TMDB", null);
        if (tentativa < NOVAS_TENTATIVAS) await esperar(esperaPadrao);
        continue;
      }

      if (resposta.ok) return resposta.json() as Promise<unknown>;

      ultimoErro = new TmdbErro(`TMDB respondeu ${resposta.status}`, resposta.status);
      if (!deveRepetir(resposta.status) || tentativa === NOVAS_TENTATIVAS) break;
      await esperar(
        resposta.status === 429 ? esperaRetryAfter(resposta, esperaPadrao) : esperaPadrao,
      );
    }

    if (ultimoErro.status !== 404) {
      console.error(`[tmdb] ${caminho}: ${ultimoErro.message}`);
    }
    throw ultimoErro;
  }

  return { requisitar };
}

let padrao: ClienteTmdb | undefined;

/** Cliente configurado pelas variáveis de ambiente do servidor. */
export function clienteTmdbPadrao(): ClienteTmdb {
  if (!padrao) {
    const env = getServerEnv();
    padrao = criarClienteTmdb({ token: env.TMDB_READ_TOKEN, baseUrl: env.TMDB_API_URL });
  }
  return padrao;
}

export type FilmeResumo = {
  id: number;
  titulo: string;
  tituloOriginal: string;
  sinopse: string;
  posterPath: string | null;
  backdropPath: string | null;
  /** IDs de gênero do TMDB. */
  generos: number[];
  ano: number | null;
  nota: number;
  votos: number;
  popularidade: number;
};

export type Pagina<T> = {
  itens: T[];
  pagina: number;
  totalPaginas: number;
  totalResultados: number;
};

export type Provedor = { id: number; nome: string; logoPath: string | null };

export type OndeAssistir = {
  link: string;
  assinatura: Provedor[];
  aluguel: Provedor[];
  compra: Provedor[];
};

export type MembroElenco = { nome: string; personagem: string; fotoPath: string | null };

export type FilmeDetalhes = Omit<FilmeResumo, "generos"> & {
  generos: { id: number; nome: string }[];
  duracaoMin: number | null;
  slogan: string | null;
  /** Key do vídeo no YouTube. */
  trailerYoutube: string | null;
  elenco: MembroElenco[];
  direcao: string[];
  ondeAssistir: OndeAssistir | null;
  parecidos: FilmeResumo[];
};

export type OrdemDescoberta = "popularidade" | "nota" | "lancamento";

export type FiltrosDescoberta = {
  /** Qualquer um destes gêneros. */
  generos?: number[];
  semGeneros?: number[];
  duracaoMin?: number;
  duracaoMax?: number;
  notaMin?: number;
  votosMin?: number;
  ordem?: OrdemDescoberta;
  pagina?: number;
};

import { z } from "zod";

/** Strings que o TMDB às vezes manda como `null` ou omite. */
const textoOpcional = z
  .string()
  .nullish()
  .transform((valor) => valor || null);

const textoOuVazio = z
  .string()
  .nullish()
  .transform((valor) => valor ?? "");

const numero = z
  .number()
  .nullish()
  .transform((valor) => valor ?? 0);

const baseFilme = {
  id: z.number().int(),
  title: z.string(),
  original_title: textoOuVazio,
  overview: textoOuVazio,
  poster_path: textoOpcional,
  backdrop_path: textoOpcional,
  release_date: textoOpcional,
  vote_average: numero,
  vote_count: numero,
  popularity: numero,
};

export const filmeTmdb = z.object({ ...baseFilme, genre_ids: z.array(z.number()).default([]) });

export function paginaTmdb<T extends z.ZodType>(item: T) {
  return z.object({
    page: z.number().int(),
    results: z.array(item),
    total_pages: z.number().int(),
    total_results: z.number().int(),
  });
}

const provedorTmdb = z.object({
  provider_id: z.number().int(),
  provider_name: z.string(),
  logo_path: textoOpcional,
});

export const detalhesTmdb = z.object({
  ...baseFilme,
  genres: z.array(z.object({ id: z.number().int(), name: z.string() })).default([]),
  runtime: z.number().nullish(),
  tagline: textoOpcional,
  videos: z
    .object({
      results: z.array(
        z.object({
          key: z.string(),
          site: z.string(),
          type: z.string(),
          official: z.boolean().default(false),
        }),
      ),
    })
    .default({ results: [] }),
  credits: z
    .object({
      cast: z.array(
        z.object({ name: z.string(), character: textoOuVazio, profile_path: textoOpcional }),
      ),
      crew: z.array(z.object({ name: z.string(), job: z.string() })),
    })
    .default({ cast: [], crew: [] }),
  "watch/providers": z
    .object({
      results: z.record(
        z.string(),
        z.object({
          link: z.string(),
          flatrate: z.array(provedorTmdb).default([]),
          rent: z.array(provedorTmdb).default([]),
          buy: z.array(provedorTmdb).default([]),
        }),
      ),
    })
    .default({ results: {} }),
  recommendations: paginaTmdb(filmeTmdb).optional(),
});

export type FilmeTmdb = z.infer<typeof filmeTmdb>;
export type DetalhesTmdb = z.infer<typeof detalhesTmdb>;

import "server-only";

import type { z } from "zod";

import {
  clienteTmdbPadrao,
  TmdbErro,
  type ClienteTmdb,
  type Parametros,
} from "@/lib/tmdb/cliente";
import {
  detalhesTmdb,
  filmeTmdb,
  paginaTmdb,
  type DetalhesTmdb,
  type FilmeTmdb,
} from "@/lib/tmdb/esquemas";
import type {
  FilmeDetalhes,
  FilmeResumo,
  FiltrosDescoberta,
  OrdemDescoberta,
  Pagina,
  Provedor,
} from "@/lib/tmdb/tipos";

const HORA = 3600;
const CACHE_LISTAS = 6 * HORA;
const CACHE_FILME = 24 * HORA;
const MAX_ELENCO = 10;
const MAX_PAGINA = 500;

const ORDENS: Record<OrdemDescoberta, string> = {
  popularidade: "popularity.desc",
  nota: "vote_average.desc",
  lancamento: "primary_release_date.desc",
};

const PAGINA_VAZIA: Pagina<never> = { itens: [], pagina: 1, totalPaginas: 0, totalResultados: 0 };

function validar<T extends z.ZodType>(esquema: T, dados: unknown): z.infer<T> {
  const resultado = esquema.safeParse(dados);
  if (!resultado.success) throw new TmdbErro("Resposta inesperada do TMDB", null);
  return resultado.data;
}

function limitarPagina(pagina = 1) {
  return Math.min(Math.max(Math.trunc(pagina), 1), MAX_PAGINA);
}

function anoDe(data: string | null): number | null {
  const ano = Number(data?.slice(0, 4));
  return ano > 0 ? ano : null;
}

function paraResumo(filme: FilmeTmdb): FilmeResumo {
  return {
    id: filme.id,
    titulo: filme.title,
    tituloOriginal: filme.original_title,
    sinopse: filme.overview,
    posterPath: filme.poster_path,
    backdropPath: filme.backdrop_path,
    generos: filme.genre_ids,
    ano: anoDe(filme.release_date),
    nota: filme.vote_average,
    votos: filme.vote_count,
    popularidade: filme.popularity,
  };
}

function paraPagina(dados: unknown): Pagina<FilmeResumo> {
  const pagina = validar(paginaTmdb(filmeTmdb), dados);
  return {
    itens: pagina.results.map(paraResumo),
    pagina: pagina.page,
    totalPaginas: pagina.total_pages,
    totalResultados: pagina.total_results,
  };
}

function trailerDe(videos: DetalhesTmdb["videos"]["results"]): string | null {
  const trailers = videos.filter((video) => video.site === "YouTube" && video.type === "Trailer");
  return (trailers.find((video) => video.official) ?? trailers[0])?.key ?? null;
}

function paraProvedores(
  lista: { provider_id: number; provider_name: string; logo_path: string | null }[],
): Provedor[] {
  return lista.map((p) => ({ id: p.provider_id, nome: p.provider_name, logoPath: p.logo_path }));
}

function paraDetalhes(filme: DetalhesTmdb): FilmeDetalhes {
  const brasil = filme["watch/providers"].results.BR;
  return {
    ...paraResumo({ ...filme, genre_ids: [] }),
    generos: filme.genres.map(({ id, name }) => ({ id, nome: name })),
    duracaoMin: filme.runtime || null,
    slogan: filme.tagline,
    trailerYoutube: trailerDe(filme.videos.results),
    elenco: filme.credits.cast.slice(0, MAX_ELENCO).map((pessoa) => ({
      nome: pessoa.name,
      personagem: pessoa.character,
      fotoPath: pessoa.profile_path,
    })),
    direcao: filme.credits.crew.filter((p) => p.job === "Director").map((p) => p.name),
    ondeAssistir: brasil
      ? {
          link: brasil.link,
          assinatura: paraProvedores(brasil.flatrate),
          aluguel: paraProvedores(brasil.rent),
          compra: paraProvedores(brasil.buy),
        }
      : null,
    parecidos: (filme.recommendations?.results ?? []).map(paraResumo),
  };
}

/** Funções de filmes sobre um cliente qualquer; os testes passam um cliente com `fetch` falso. */
export function criarApiFilmes(cliente: ClienteTmdb) {
  return {
    async descobrirFilmes(filtros: FiltrosDescoberta = {}): Promise<Pagina<FilmeResumo>> {
      const parametros: Parametros = {
        with_genres: filtros.generos?.length ? filtros.generos.join("|") : undefined,
        without_genres: filtros.semGeneros?.length ? filtros.semGeneros.join(",") : undefined,
        "with_runtime.gte": filtros.duracaoMin,
        "with_runtime.lte": filtros.duracaoMax,
        "vote_average.gte": filtros.notaMin,
        "vote_count.gte": filtros.votosMin,
        sort_by: ORDENS[filtros.ordem ?? "popularidade"],
        page: limitarPagina(filtros.pagina),
        region: "BR",
        include_adult: false,
      };
      return paraPagina(await cliente.requisitar("/discover/movie", parametros, CACHE_LISTAS));
    },

    async obterFilme(id: number): Promise<FilmeDetalhes | null> {
      try {
        const dados = await cliente.requisitar(
          `/movie/${id}`,
          { append_to_response: "videos,credits,watch/providers,recommendations" },
          CACHE_FILME,
        );
        return paraDetalhes(validar(detalhesTmdb, dados));
      } catch (erro) {
        if (erro instanceof TmdbErro && erro.status === 404) return null;
        throw erro;
      }
    },

    async recomendacoesDe(id: number, pagina = 1): Promise<Pagina<FilmeResumo>> {
      const dados = await cliente.requisitar(
        `/movie/${id}/recommendations`,
        { page: limitarPagina(pagina) },
        CACHE_FILME,
      );
      return paraPagina(dados);
    },

    async buscarFilmes(texto: string, pagina = 1): Promise<Pagina<FilmeResumo>> {
      const consulta = texto.trim();
      if (!consulta) return PAGINA_VAZIA;
      const dados = await cliente.requisitar(
        "/search/movie",
        { query: consulta, page: limitarPagina(pagina), region: "BR", include_adult: false },
        CACHE_LISTAS,
      );
      return paraPagina(dados);
    },
  };
}

type ApiFilmes = ReturnType<typeof criarApiFilmes>;

let padrao: ApiFilmes | undefined;
const api = () => (padrao ??= criarApiFilmes(clienteTmdbPadrao()));

export const descobrirFilmes: ApiFilmes["descobrirFilmes"] = (...args) =>
  api().descobrirFilmes(...args);
export const obterFilme: ApiFilmes["obterFilme"] = (...args) => api().obterFilme(...args);
export const recomendacoesDe: ApiFilmes["recomendacoesDe"] = (...args) =>
  api().recomendacoesDe(...args);
export const buscarFilmes: ApiFilmes["buscarFilmes"] = (...args) => api().buscarFilmes(...args);

export type TamanhoImagem = "w92" | "w185" | "w342" | "w500" | "w780" | "w1280" | "original";

/** URL do CDN de imagens do TMDB. Pode ser usado no servidor e no navegador. */
export function urlImagem(path: string | null, tamanho: TamanhoImagem): string | null {
  return path ? `https://image.tmdb.org/t/p/${tamanho}${path}` : null;
}

