import type { FilmeResumo } from "@/lib/tmdb/tipos";

/** Filme mínimo para os testes do motor. */
export function filme(id: number, sobrescrever: Partial<FilmeResumo> = {}): FilmeResumo {
  return {
    id,
    titulo: `Filme ${id}`,
    tituloOriginal: `Film ${id}`,
    sinopse: "",
    posterPath: null,
    backdropPath: null,
    generos: [18],
    ano: 2020,
    nota: 7,
    votos: 1000,
    popularidade: 50,
    ...sobrescrever,
  };
}

/** Gerador "aleatório" fixo, para testes que não dependem do sorteio. */
export const geradorFixo = (valor = 0) => () => valor;

import { describe, expect, it } from "vitest";

import { filtrosDeDuracao, PERFIS } from "@/features/recomendacao/perfil";
import { criarGerador, diaEmSaoPaulo, sortearInteiro } from "@/features/recomendacao/semente";

describe("perfil", () => {
  it.each([
    ["curta", { duracaoMax: 90 }],
    ["media", { duracaoMin: 90, duracaoMax: 120 }],
    ["longa", { duracaoMin: 120 }],
    ["indiferente", {}],
  ] as const)("duração %s vira %j", (duracao, filtros) => {
    expect(filtrosDeDuracao(duracao)).toEqual(filtros);
  });

  it("cada frequência tem votos, nota e páginas da tabela", () => {
    expect(PERFIS).toEqual({
      raramente: { votosMin: 2000, notaMin: 7, paginaMax: 2 },
      mensal: { votosMin: 1000, notaMin: 6.5, paginaMax: 3 },
      semanal: { votosMin: 300, notaMin: 6.5, paginaMax: 5 },
      diaria: { votosMin: 100, notaMin: 6, paginaMax: 10 },
    });
  });
});

describe("semente", () => {
  const sequencia = (gerador: () => number) => Array.from({ length: 5 }, gerador);
  const hoje = new Date("2026-10-05T15:00:00Z");

  it("a mesma entrada gera a mesma sequência", () => {
    expect(sequencia(criarGerador("u1", hoje, 0))).toEqual(sequencia(criarGerador("u1", hoje, 0)));
  });

  it("mudar rodada, dia ou usuário muda a sequência", () => {
    const base = sequencia(criarGerador("u1", hoje, 0));
    expect(sequencia(criarGerador("u1", hoje, 1))).not.toEqual(base);
    expect(sequencia(criarGerador("u1", new Date("2026-10-06T15:00:00Z"), 0))).not.toEqual(base);
    expect(sequencia(criarGerador("u2", hoje, 0))).not.toEqual(base);
  });

  it("gera números em [0, 1)", () => {
    for (const valor of Array.from({ length: 1000 }, criarGerador("u1", hoje, 3))) {
      expect(valor).toBeGreaterThanOrEqual(0);
      expect(valor).toBeLessThan(1);
    }
  });

  it("conta o dia no fuso de São Paulo", () => {
    expect(diaEmSaoPaulo(new Date("2026-10-05T02:00:00Z"))).toBe("2026-10-04");
    expect(diaEmSaoPaulo(new Date("2026-10-05T23:00:00Z"))).toBe("2026-10-05");
    expect(sequencia(criarGerador("u1", new Date("2026-10-05T02:00:00Z"), 0))).not.toEqual(
      sequencia(criarGerador("u1", new Date("2026-10-05T23:00:00Z"), 0)),
    );
  });

  it("sortearInteiro fica dentro da faixa, inclusive nas pontas", () => {
    expect(sortearInteiro(() => 0, 1, 5)).toBe(1);
    expect(sortearInteiro(() => 0.9999, 1, 5)).toBe(5);
  });
});

import { describe, expect, it } from "vitest";

import { planejar } from "@/features/recomendacao/planejar";
import { criarGerador } from "@/features/recomendacao/semente";
import type { AvaliacaoMotor, EntradaMotor } from "@/features/recomendacao/tipos";

function entrada(sobrescrever: Partial<EntradaMotor> = {}): EntradaMotor {
  return {
    preferencias: { generos: [53, 18, 28], duracao: "media", frequencia: "semanal" },
    usuarioId: "u1",
    data: new Date("2026-10-05T15:00:00Z"),
    ...sobrescrever,
  };
}

const avaliacao = (tmdbId: number, nota: AvaliacaoMotor["nota"]): AvaliacaoMotor => ({
  tmdbId,
  titulo: `Filme ${tmdbId}`,
  nota,
  generos: [18],
});

describe("planejar", () => {
  it("gera 2 consultas 'para você' em páginas diferentes e 1 por gênero, na ordem de GENEROS", () => {
    for (let rodada = 0; rodada < 30; rodada++) {
      const plano = planejar(entrada({ rodada }), criarGerador("u1", new Date(), rodada));
      const paraVoce = plano.filter((c) => c.tipo === "para-voce");

      expect(paraVoce).toHaveLength(2);
      const [a, b] = paraVoce.map((c) => (c.tipo === "para-voce" ? c.filtros : undefined));
      expect(a?.pagina).not.toBe(b?.pagina);
      for (const filtros of [a, b]) {
        expect(filtros).toMatchObject({
          generos: [53, 18, 28],
          duracaoMin: 90,
          duracaoMax: 120,
          votosMin: 300,
          notaMin: 6.5,
          ordem: "popularidade",
        });
        expect(filtros?.pagina).toBeGreaterThanOrEqual(1);
        expect(filtros?.pagina).toBeLessThanOrEqual(5);
      }

      const porGenero = plano.filter((c) => c.tipo === "genero");
      expect(porGenero.map((c) => (c.tipo === "genero" ? c.generoId : 0))).toEqual([28, 18, 53]);
    }
  });

  it("com frequência 'raramente' as páginas ficam entre 1 e 2", () => {
    const plano = planejar(
      entrada({ preferencias: { generos: [18], duracao: "indiferente", frequencia: "raramente" } }),
      criarGerador("u1", new Date(), 0),
    );
    const paginas = plano.flatMap((c) => (c.tipo === "genero" ? [] : [c.tipo === "para-voce" ? c.filtros.pagina : 0]));
    expect(paginas.sort()).toEqual([1, 2]);
  });

  it("gera 1 consulta de parecidos por avaliação 4★ ou 5★, no máximo 3, as mais altas primeiro", () => {
    const plano = planejar(
      entrada({
        avaliacoes: [
          avaliacao(1, 4),
          avaliacao(2, 3),
          avaliacao(3, 5),
          avaliacao(4, 1),
          avaliacao(5, 4),
          avaliacao(6, 5),
        ],
      }),
      criarGerador("u1", new Date(), 0),
    );
    const origens = plano.flatMap((c) => (c.tipo === "parecidos" ? [c.origem.tmdbId] : []));
    expect(origens).toEqual([3, 6, 1]);
  });

  it("sem avaliações não há consultas de parecidos", () => {
    const plano = planejar(entrada(), criarGerador("u1", new Date(), 0));
    expect(plano.some((c) => c.tipo === "parecidos")).toBe(false);
  });
});

import { describe, expect, it } from "vitest";

import { motivoParecido, motivoPorGeneros } from "@/features/recomendacao/motivo";
import { agregarParecidos } from "@/features/recomendacao/parecidos";
import { bonusPorGenero, pontuar } from "@/features/recomendacao/ranquear";
import type { AvaliacaoMotor } from "@/features/recomendacao/tipos";

import { filme, geradorFixo } from "./fabrica";

const contexto = (favoritos: number[], bonus = new Map<number, number>()) => ({
  favoritos,
  bonus,
  gerador: geradorFixo(0),
});

const ordemIds = (lista: { id: number }[]) => lista.map((f) => f.id);

describe("pontuar", () => {
  it("filme de gênero favorito fica à frente de um sem gênero favorito", () => {
    const resultado = pontuar([filme(1, { generos: [27] }), filme(2, { generos: [18] })], contexto([18]));
    expect(ordemIds(resultado)).toEqual([2, 1]);
  });

  it("com afinidade igual, nota maior fica à frente", () => {
    const resultado = pontuar([filme(1, { nota: 6 }), filme(2, { nota: 9 })], contexto([18]));
    expect(ordemIds(resultado)).toEqual([2, 1]);
  });

  it("aplica a fórmula 0.5 afinidade + 0.3 nota + 0.2 popularidade", () => {
    const [unico] = pontuar([filme(1, { generos: [18, 27], nota: 8, popularidade: 99 })], contexto([18]));
    // afinidade 1/2, nota 0.8, popularidade é a maior, então 1.
    expect(unico?.pontuacao).toBeCloseTo(0.5 * 0.5 + 0.3 * 0.8 + 0.2 * 1);
  });

  it("o bônus de uma avaliação 5★ sobe filmes do mesmo gênero", () => {
    const filmes = [filme(1, { generos: [27] }), filme(2, { generos: [35] })];
    const avaliacoes: AvaliacaoMotor[] = [{ tmdbId: 9, titulo: "X", nota: 5, generos: [35] }];

    expect(ordemIds(pontuar(filmes, contexto([27, 35])))).toEqual([1, 2]);
    expect(ordemIds(pontuar(filmes, contexto([27, 35], bonusPorGenero(avaliacoes))))).toEqual([2, 1]);
  });

  it("bonusPorGenero soma os pesos por estrela", () => {
    const bonus = bonusPorGenero([
      { tmdbId: 1, titulo: "A", nota: 5, generos: [18, 53] },
      { tmdbId: 2, titulo: "B", nota: 1, generos: [18] },
      { tmdbId: 3, titulo: "C", nota: 4, generos: [53] },
    ]);
    expect(bonus.get(18)).toBeCloseTo(0);
    expect(bonus.get(53)).toBeCloseTo(0.15);
  });
});

describe("agregarParecidos", () => {
  const origem = (tmdbId: number, nota: AvaliacaoMotor["nota"]): AvaliacaoMotor => ({
    tmdbId,
    titulo: `Origem ${tmdbId}`,
    nota,
    generos: [18],
  });

  it("filme presente nas listas de duas origens fica à frente de um presente em só uma", () => {
    const secoes = agregarParecidos(
      [
        { origem: origem(100, 5), filmes: [filme(1), filme(2)] },
        { origem: origem(200, 5), filmes: [filme(3), filme(2)] },
      ],
      new Set(),
    );
    const todos = secoes.flatMap((s) => s.filmes);
    expect(todos[0]?.id).toBe(2);
  });

  it("origem 5★ pesa mais que 4★", () => {
    const secoes = agregarParecidos(
      [
        { origem: origem(100, 4), filmes: [filme(1)] },
        { origem: origem(200, 5), filmes: [filme(2)] },
      ],
      new Set(),
    );
    expect(secoes.map((s) => s.origem.tmdbId)).toEqual([200, 100]);
    expect(secoes[0]?.filmes[0]?.peso).toBeCloseTo(1);
    expect(secoes[1]?.filmes[0]?.peso).toBeCloseTo(0.6);
  });

  it("não devolve filmes excluídos nem os próprios filmes avaliados", () => {
    const secoes = agregarParecidos(
      [
        { origem: origem(100, 5), filmes: [filme(200), filme(7), filme(8)] },
        { origem: origem(200, 5), filmes: [filme(100), filme(9)] },
      ],
      new Set([8]),
    );
    expect(secoes.flatMap((s) => ordemIds(s.filmes)).sort()).toEqual([7, 9]);
  });
});

describe("motivo", () => {
  it.each([
    [[18], "Porque você curte Drama"],
    [[53, 18], "Porque você curte Drama e Thriller"],
    [[80, 53, 18, 28], "Porque você curte Ação, Crime e Drama"],
    [[99], "Popular entre quem tem gostos parecidos"],
  ])("gêneros %j viram '%s'", (generos, texto) => {
    expect(motivoPorGeneros(generos, [18, 53, 80, 28])).toBe(texto);
  });

  it("explica os parecidos", () => {
    expect(motivoParecido({ tmdbId: 1, titulo: "Interestelar", nota: 5, generos: [] })).toBe(
      "Parecido com Interestelar, que você deu 5★",
    );
  });
});

import { describe, expect, it, vi } from "vitest";

import { gerarRecomendacoes, type ApiMotor } from "@/features/recomendacao/gerar";
import type { EntradaMotor } from "@/features/recomendacao/tipos";
import { TmdbErro } from "@/lib/tmdb/cliente";
import type { FiltrosDescoberta, Pagina } from "@/lib/tmdb/tipos";

import { filme } from "./fabrica";

const pagina = (itens: ReturnType<typeof filme>[]): Pagina<ReturnType<typeof filme>> => ({
  itens,
  pagina: 1,
  totalPaginas: 1,
  totalResultados: itens.length,
});

/** TMDB falso: "para você" devolve 30 filmes de drama/terror; cada gênero, 25 do próprio gênero. */
function apiFalsa(falharGenero?: number): ApiMotor {
  return {
    descobrirFilmes: vi.fn(async (filtros: FiltrosDescoberta = {}) => {
      const generos = filtros.generos ?? [];
      if (generos.length > 1) {
        const base = (filtros.pagina ?? 1) * 1000;
        return pagina(
          Array.from({ length: 30 }, (_, i) =>
            filme(base + i, { generos: [i % 2 ? 18 : 27], popularidade: 100 - i }),
          ),
        );
      }
      const [genero] = generos;
      if (genero === falharGenero) throw new TmdbErro("TMDB respondeu 503", 503);
      return pagina(
        Array.from({ length: 25 }, (_, i) =>
          // Os 5 primeiros repetem filmes que podem estar em "para você".
          filme(i < 5 ? 1000 + i : (genero ?? 0) * 100 + i, { generos: [genero ?? 0] }),
        ),
      );
    }),
    recomendacoesDe: vi.fn(async (id: number) =>
      pagina([filme(id + 1, { titulo: `Parecido ${id}` }), filme(5000)]),
    ),
  };
}

