  });

  it("inclui as seções de parecidos depois de 'para você' e exclui os avaliados", async () => {
    const secoes = await gerarRecomendacoes(
      {
        ...entrada,
        avaliacoes: [
          { tmdbId: 700, titulo: "Interestelar", nota: 5, generos: [878] },
