import type { Duracao, Frequencia } from "@/features/preferencias/opcoes";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

export type AvaliacaoMotor = {
  tmdbId: number;
  titulo: string;
  nota: 1 | 2 | 3 | 4 | 5;
  /** Gêneros do filme avaliado, para o bônus de afinidade. */
  generos: number[];
};

export type EntradaMotor = {
  preferencias: { generos: number[]; duracao: Duracao; frequencia: Frequencia };
  usuarioId: string;
  /** "Hoje"; o dia é contado no fuso America/Sao_Paulo. */
  data: Date;
  /** Cada "Gerar outras recomendações" soma 1. Padrão 0. */
  rodada?: number;
  avaliacoes?: AvaliacaoMotor[];
  /** IDs do TMDB que nunca devem aparecer. */
  excluir?: number[];
};

export type Recomendacao = FilmeResumo & { motivo: string; pontuacao: number };

export type Secao = {
  /** "para-voce", "parecidos-{tmdbId}" ou "genero-{id}". */
  id: string;
  titulo: string;
  filmes: Recomendacao[];
  /** A consulta desta seção falhou; `filmes` vem vazio. */
  erro?: true;
};

/** Gerador pseudoaleatório: devolve números em [0, 1). */
export type Gerador = () => number;

import type { Duracao, Frequencia } from "@/features/preferencias/opcoes";
import type { FiltrosDescoberta } from "@/lib/tmdb/tipos";

export function filtrosDeDuracao(
  duracao: Duracao,
): Pick<FiltrosDescoberta, "duracaoMin" | "duracaoMax"> {
  switch (duracao) {
    case "curta":
      return { duracaoMax: 90 };
    case "media":
      return { duracaoMin: 90, duracaoMax: 120 };
    case "longa":
      return { duracaoMin: 120 };
    case "indiferente":
      return {};
  }
}

/**
 * Quanto mais a pessoa assiste, menos óbvios os filmes: menos votos e nota mínimos
 * e páginas mais fundas do TMDB. Quem assiste pouco recebe os consagrados.
 */
export const PERFIS: Record<Frequencia, { votosMin: number; notaMin: number; paginaMax: number }> =
  {
    raramente: { votosMin: 2000, notaMin: 7, paginaMax: 2 },
    mensal: { votosMin: 1000, notaMin: 6.5, paginaMax: 3 },
    semanal: { votosMin: 300, notaMin: 6.5, paginaMax: 5 },
    diaria: { votosMin: 100, notaMin: 6, paginaMax: 10 },
  };

import type { Gerador } from "@/features/recomendacao/tipos";

const formatoDia = new Intl.DateTimeFormat("en-CA", {
  timeZone: "America/Sao_Paulo",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
});

/** Data no formato AAAA-MM-DD, no fuso de São Paulo. */
export function diaEmSaoPaulo(data: Date): string {
  return formatoDia.format(data);
}

/** Hash FNV-1a de 32 bits. */
function hash(texto: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < texto.length; i++) {
    h ^= texto.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** Mulberry32: gerador pequeno, rápido e determinístico. */
function mulberry32(semente: number): Gerador {
  let estado = semente;
  return () => {
    estado = (estado + 0x6d2b79f5) | 0;
    let t = estado;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Mesmo usuário, mesmo dia e mesma rodada sempre produzem a mesma sequência. */
export function criarGerador(usuarioId: string, data: Date, rodada: number): Gerador {
  return mulberry32(hash(`${usuarioId}|${diaEmSaoPaulo(data)}|${rodada}`));
}

/** Inteiro entre `min` e `max`, inclusive. */
export function sortearInteiro(gerador: Gerador, min: number, max: number): number {
  return min + Math.floor(gerador() * (max - min + 1));
}

import { GENEROS } from "@/features/preferencias/generos";
import { filtrosDeDuracao, PERFIS } from "@/features/recomendacao/perfil";
import { sortearInteiro } from "@/features/recomendacao/semente";
import type { AvaliacaoMotor, EntradaMotor, Gerador } from "@/features/recomendacao/tipos";
import type { FiltrosDescoberta } from "@/lib/tmdb/tipos";

export type Consulta =
  | { tipo: "para-voce"; filtros: FiltrosDescoberta }
  | { tipo: "parecidos"; origem: AvaliacaoMotor }
  | { tipo: "genero"; generoId: number; filtros: FiltrosDescoberta };

const MAX_ORIGENS_PARECIDOS = 3;

/** Avaliações de 4★ e 5★ que viram fonte de parecidos: as mais altas, até 3. */
export function origensDeParecidos(avaliacoes: AvaliacaoMotor[] = []): AvaliacaoMotor[] {
  return avaliacoes
    .filter((avaliacao) => avaliacao.nota >= 4)
    .sort((a, b) => b.nota - a.nota)
    .slice(0, MAX_ORIGENS_PARECIDOS);
}

export function planejar({ preferencias, avaliacoes }: EntradaMotor, gerador: Gerador): Consulta[] {
  const perfil = PERFIS[preferencias.frequencia];
  const base: FiltrosDescoberta = {
    ...filtrosDeDuracao(preferencias.duracao),
    votosMin: perfil.votosMin,
    notaMin: perfil.notaMin,
    ordem: "popularidade",
  };

  const primeira = sortearInteiro(gerador, 1, perfil.paginaMax);
  let segunda = sortearInteiro(gerador, 1, perfil.paginaMax - 1);
  if (segunda >= primeira) segunda += 1;

  const paraVoce: Consulta[] =
    perfil.paginaMax > 1
      ? [primeira, segunda].map((pagina) => ({
          tipo: "para-voce",
          filtros: { ...base, generos: preferencias.generos, pagina },
        }))
      : (["popularidade", "nota"] as const).map((ordem) => ({
          tipo: "para-voce",
          filtros: { ...base, generos: preferencias.generos, ordem, pagina: 1 },
        }));

  const parecidos: Consulta[] = origensDeParecidos(avaliacoes).map((origem) => ({
    tipo: "parecidos",
    origem,
  }));

  const porGenero: Consulta[] = GENEROS.filter(({ id }) => preferencias.generos.includes(id)).map(
    ({ id }) => ({
      tipo: "genero",
      generoId: id,
      filtros: { ...base, generos: [id], pagina: sortearInteiro(gerador, 1, perfil.paginaMax) },
    }),
  );

  return [...paraVoce, ...parecidos, ...porGenero];
}

import type { AvaliacaoMotor, Gerador } from "@/features/recomendacao/tipos";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

const PESO_POR_ESTRELA: Record<AvaliacaoMotor["nota"], number> = {
  5: 0.1,
  4: 0.05,
  3: 0,
  2: -0.05,
  1: -0.1,
};

const DESEMPATE_MAX = 0.02;

/** Soma, por gênero, o peso das estrelas dadas a filmes daquele gênero. */
export function bonusPorGenero(avaliacoes: AvaliacaoMotor[] = []): Map<number, number> {
  const bonus = new Map<number, number>();
  for (const { nota, generos } of avaliacoes) {
    for (const genero of generos) {
      bonus.set(genero, (bonus.get(genero) ?? 0) + PESO_POR_ESTRELA[nota]);
    }
  }
  return bonus;
}

type Contexto = {
  favoritos: number[];
  bonus: Map<number, number>;
  gerador: Gerador;
};

function afinidade(filme: FilmeResumo, { favoritos, bonus }: Contexto): number {
  const total = Math.max(1, filme.generos.length);
  const emComum = filme.generos.filter((genero) => favoritos.includes(genero)).length;
  const extra = filme.generos.reduce((soma, genero) => soma + (bonus.get(genero) ?? 0), 0) / total;
  return Math.min(1, Math.max(0, emComum / total + extra));
}

/**
 * pontuacao = 0.5 afinidade + 0.3 nota + 0.2 popularidade + desempate,
 * com a popularidade normalizada em escala log pela maior da lista.
 * Devolve os filmes em ordem decrescente de pontuação.
 */
export function pontuar<F extends FilmeResumo>(
  filmes: F[],
  contexto: Contexto,
): (F & { pontuacao: number })[] {
  const maiorPopularidade = Math.max(0, ...filmes.map((filme) => filme.popularidade));
  const escala = Math.log10(1 + maiorPopularidade) || 1;

  // O sorteio do desempate segue a ordem dos IDs, para não depender da ordem da API.
  const desempate = new Map(
    [...filmes]
      .sort((a, b) => a.id - b.id)
      .map((filme) => [filme.id, contexto.gerador() * DESEMPATE_MAX]),
  );

  return filmes
    .map((filme) => ({
      ...filme,
      pontuacao:
        0.5 * afinidade(filme, contexto) +
        0.3 * (filme.nota / 10) +
        0.2 * (Math.log10(1 + filme.popularidade) / escala) +
        (desempate.get(filme.id) ?? 0),
    }))
    .sort((a, b) => b.pontuacao - a.pontuacao);
}

import type { AvaliacaoMotor } from "@/features/recomendacao/tipos";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

const PESO_ORIGEM: Partial<Record<AvaliacaoMotor["nota"], number>> = { 5: 1, 4: 0.6 };
const MAX_POR_SECAO = 20;

export type ListaDeParecidos = { origem: AvaliacaoMotor; filmes: FilmeResumo[] };
export type SecaoParecidos = {
  origem: AvaliacaoMotor;
  filmes: (FilmeResumo & { peso: number })[];
};

/**
 * Junta as recomendações do TMDB de cada filme bem avaliado. Cada candidato soma
 * `peso da origem × (1 − posição / tamanho da lista)` em todas as listas em que aparece,
 * e fica na seção da origem que mais contribuiu para ele.
 */
export function agregarParecidos(
  listas: ListaDeParecidos[],
  excluir: ReadonlySet<number>,
): SecaoParecidos[] {
  const avaliados = new Set(listas.map(({ origem }) => origem.tmdbId));
  const candidatos = new Map<
    number,
    { filme: FilmeResumo; peso: number; melhorOrigem: AvaliacaoMotor; melhorContribuicao: number }
  >();

  for (const { origem, filmes } of listas) {
    const pesoOrigem = PESO_ORIGEM[origem.nota] ?? 0;
    filmes.forEach((filme, posicao) => {
      if (excluir.has(filme.id) || avaliados.has(filme.id)) return;
      const contribuicao = pesoOrigem * (1 - posicao / filmes.length);
      const atual = candidatos.get(filme.id);
      if (!atual) {
        candidatos.set(filme.id, {
          filme,
          peso: contribuicao,
          melhorOrigem: origem,
          melhorContribuicao: contribuicao,
        });
        return;
      }
      atual.peso += contribuicao;
      if (contribuicao > atual.melhorContribuicao) {
        atual.melhorOrigem = origem;
        atual.melhorContribuicao = contribuicao;
      }
    });
  }

  const ordenados = [...candidatos.values()].sort((a, b) => b.peso - a.peso);
  const secoes = new Map<number, SecaoParecidos>();
  for (const { filme, peso, melhorOrigem } of ordenados) {
    const secao = secoes.get(melhorOrigem.tmdbId) ?? { origem: melhorOrigem, filmes: [] };
    if (secao.filmes.length < MAX_POR_SECAO) secao.filmes.push({ ...filme, peso });
    secoes.set(melhorOrigem.tmdbId, secao);
  }
  // A ordem de inserção já segue o candidato mais bem colocado de cada origem.
  return [...secoes.values()];
}

import { GENEROS } from "@/features/preferencias/generos";
import type { AvaliacaoMotor } from "@/features/recomendacao/tipos";

const MAX_GENEROS_NO_MOTIVO = 3;

function listar(nomes: string[]): string {
  if (nomes.length <= 1) return nomes.join("");
  return `${nomes.slice(0, -1).join(", ")} e ${nomes.at(-1)}`;
}

/** "Porque você curte Drama e Thriller", com no máximo 3 gêneros, na ordem de GENEROS. */
export function motivoPorGeneros(generosDoFilme: number[], favoritos: number[]): string {
  const emComum = GENEROS.filter(
    ({ id }) => generosDoFilme.includes(id) && favoritos.includes(id),
  ).map(({ nome }) => nome);
  if (emComum.length === 0) return "Popular entre quem tem gostos parecidos";
  return `Porque você curte ${listar(emComum.slice(0, MAX_GENEROS_NO_MOTIVO))}`;
}

export function motivoParecido(origem: AvaliacaoMotor): string {
  return `Parecido com ${origem.titulo}, que você deu ${origem.nota}★`;
}

