import type { Recomendacao } from "@/features/recomendacao/tipos";
import { urlImagem } from "@/lib/tmdb/imagens";

export function CartaoFilme({ filme }: { filme: Recomendacao }) {
  const poster = urlImagem(filme.posterPath, "w342");
  const nome = filme.ano ? `${filme.titulo} (${filme.ano})` : filme.titulo;
  const detalhes = [filme.ano, `★ ${filme.nota.toFixed(1)}`].filter(Boolean).join(" · ");

  return (
    <Link
      href={`/filme/${filme.id}`}
      aria-label={nome}
      className="group focus-visible:ring-ring/50 flex w-40 flex-col gap-2 rounded-lg outline-none focus-visible:ring-3 md:w-44"
    >
      <div className="bg-muted relative aspect-[2/3] overflow-hidden rounded-lg">
        {poster ? (
          <Image
            src={poster}
            alt=""
            fill
            sizes="(min-width: 768px) 176px, 160px"
            className="object-cover transition-transform duration-300 group-hover:scale-105"
          />
        ) : (
          <div
            data-testid="sem-poster"
            className="text-muted-foreground flex h-full items-center justify-center p-3 text-center text-sm font-medium"
          >
            {filme.titulo}
          </div>
        )}
      </div>
      <div className="flex flex-col gap-0.5">
        <p className="truncate text-sm font-medium">{filme.titulo}</p>
        <p className="text-muted-foreground text-xs">{detalhes}</p>
        <p className="text-muted-foreground line-clamp-2 text-xs">{filme.motivo}</p>
      </div>
    </Link>
  );
}

"use client";

import { ChevronLeft, ChevronRight } from "lucide-react";
import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";

import { Button } from "@/components/ui/button";

/**
 * Lista com rolagem horizontal nativa (toque, trackpad e teclado funcionam sem JS).
 * No desktop, as setas rolam cerca de uma largura visível.
 */
export function Carrossel({ rotulo, children }: { rotulo: string; children: ReactNode }) {
  const lista = useRef<HTMLUListElement>(null);
  const [noInicio, setNoInicio] = useState(true);
  const [noFim, setNoFim] = useState(false);

  const atualizar = useCallback(() => {
    const elemento = lista.current;
    if (!elemento) return;
    setNoInicio(elemento.scrollLeft <= 1);
    setNoFim(elemento.scrollLeft + elemento.clientWidth >= elemento.scrollWidth - 1);
  }, []);

  useEffect(() => {
    atualizar();
    window.addEventListener("resize", atualizar);
    return () => window.removeEventListener("resize", atualizar);
  }, [atualizar]);

  function rolar(direcao: 1 | -1) {
    const elemento = lista.current;
    if (!elemento) return;
    elemento.scrollBy({ left: direcao * elemento.clientWidth * 0.9, behavior: "smooth" });
  }

  return (
    <div className="relative">
      <ul
        ref={lista}
        onScroll={atualizar}
        className="flex snap-x snap-mandatory gap-4 overflow-x-auto scroll-smooth pb-2 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {children}
      </ul>
      <div className="pointer-events-none absolute inset-y-0 -right-2 -left-2 hidden items-start justify-between pt-28 md:flex">
        <Button
          variant="secondary"
          size="icon"
          aria-label={`Anterior em ${rotulo}`}
          disabled={noInicio}
          onClick={() => rolar(-1)}
          className="pointer-events-auto rounded-full shadow-md disabled:invisible"
        >
          <ChevronLeft />
        </Button>
        <Button
          variant="secondary"
          size="icon"
          aria-label={`Próximo em ${rotulo}`}
          disabled={noFim}
          onClick={() => rolar(1)}
          className="pointer-events-auto rounded-full shadow-md disabled:invisible"
        >
          <ChevronRight />
        </Button>
      </div>
    </div>
  );
}

import Link from "next/link";

import { buttonVariants } from "@/components/ui/button";
import { Carrossel } from "@/features/dashboard/components/carrossel";
import { CartaoFilme } from "@/features/dashboard/components/cartao-filme";
import type { Secao } from "@/features/recomendacao/tipos";

type Props = {
  secao: Secao;
  /** URL atual (com a rodada), usada no "Tentar de novo". */
  urlAtual: string;
};

export function SecaoRecomendacoes({ secao, urlAtual }: Props) {
  const idTitulo = `secao-${secao.id}`;

  return (
    <section aria-labelledby={idTitulo} className="flex flex-col gap-3">
      <h2 id={idTitulo} className="text-xl font-semibold tracking-tight">
        {secao.titulo}
      </h2>
      {secao.erro ? (
        <div className="border-border/60 text-muted-foreground flex flex-wrap items-center gap-3 rounded-lg border border-dashed px-4 py-6 text-sm">
          <p>Não foi possível carregar agora.</p>
          <Link href={urlAtual} className={buttonVariants({ variant: "outline", size: "sm" })}>
            Tentar de novo
          </Link>
        </div>
      ) : (
        <Carrossel rotulo={secao.titulo}>
          {secao.filmes.map((filme) => (
            <li key={filme.id} className="shrink-0 snap-start">
              <CartaoFilme filme={filme} />
            </li>
          ))}
        </Carrossel>
      )}
    </section>
  );
}

