cat > tests/e2e/zz-debug.spec.ts <<'EOF'
import { test } from "@playwright/test";
import { emailAleatorio } from "../support/supabase-local";
import { cadastrar, concluirOnboarding } from "./helpers";
test("debug", async ({ page }) => {
  const logs: string[] = [];
  page.on("console", (m) => logs.push(`[${m.type()}] ${m.text().slice(0, 300)}`));
  page.on("pageerror", (e) => logs.push(`[pageerror] ${e.message.slice(0, 300)}`));
  page.on("response", (r) => { if (r.status() >= 400 || r.request().method() === "POST") logs.push(`[${r.status()}] ${r.request().method()} ${r.url()}`); });
  await cadastrar(page, "Debug", emailAleatorio("e2e"));
  try { await concluirOnboarding(page); } catch (e) { logs.push("onboarding: " + String(e).slice(0, 200)); }
  await page.waitForTimeout(3000);
  logs.push("URL " + page.url());
  logs.push("MAIN " + (await page.getByRole("main").innerText()).slice(0, 200));
  await page.reload();
  await page.waitForTimeout(3000);
  logs.push("RELOAD MAIN " + (await page.getByRole("main").innerText()).slice(0, 200));
  console.log(logs.join("\n"));
});
EOF
