            <div className="text-muted-foreground flex h-full items-center justify-center p-3 text-center font-medium">
              {filme.titulo}
            </div>
          )}
        </div>

        <div className="flex flex-col gap-3">
          <div>
            <h1 className="text-3xl font-bold tracking-tight sm:text-4xl">{filme.titulo}</h1>
            {filme.tituloOriginal && filme.tituloOriginal !== filme.titulo && (
              <p className="text-muted-foreground mt-1">{filme.tituloOriginal}</p>
            )}
          </div>
          <ul className="text-muted-foreground flex flex-wrap gap-x-3 gap-y-1 text-sm">
            {dados.map((item, indice) => (
              <li key={item} className="flex items-center gap-3">
                {indice > 0 && <span aria-hidden="true">·</span>}
                <span>{item}</span>
              </li>
            ))}
          </ul>
          {filme.generos.length > 0 && (
            <ul aria-label="Gêneros" className="flex flex-wrap gap-2">
              {filme.generos.map((genero) => (
                <li
                  key={genero.id}
                  className="border-border bg-background/60 rounded-full border px-3 py-1 text-xs"
                >
                  {genero.nome}
                </li>
              ))}
            </ul>
          )}
          {filme.slogan && <p className="text-muted-foreground italic">{filme.slogan}</p>}
          {/* Botões de avaliação, listas e "não me interessa" entram aqui nas próximas specs. */}
          <div data-testid="acoes-filme" className="flex flex-wrap gap-2 empty:hidden" />
        </div>
      </div>
    </div>
  );
}

import { ExternalLink } from "lucide-react";
import Image from "next/image";

import { urlImagem } from "@/lib/tmdb/imagens";
import type { OndeAssistir as Dados, Provedor } from "@/lib/tmdb/tipos";

const GRUPOS = [
  { chave: "assinatura", titulo: "Assinatura" },
  { chave: "aluguel", titulo: "Aluguel" },
  { chave: "compra", titulo: "Compra" },
] as const;

function Provedores({ titulo, provedores }: { titulo: string; provedores: Provedor[] }) {
  return (
    <div className="flex flex-col gap-2">
      <h3 className="text-muted-foreground text-sm font-medium">{titulo}</h3>
      <ul className="flex flex-wrap gap-3">
        {provedores.map((provedor) => {
          const logo = urlImagem(provedor.logoPath, "w92");
          return (
            <li key={provedor.id} className="flex items-center gap-2">
              {logo ? (
                <Image
                  src={logo}
                  alt={provedor.nome}
                  width={36}
                  height={36}
                  className="rounded-md"
                />
              ) : (
                <span aria-hidden="true" className="bg-muted size-9 rounded-md" />
              )}
              <span className="text-sm">{provedor.nome}</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export function OndeAssistir({ dados }: { dados: Dados | null }) {
  const grupos = GRUPOS.filter(({ chave }) => dados && dados[chave].length > 0);

  if (!dados || grupos.length === 0) {
    return (
      <p className="text-muted-foreground">Não encontramos onde assistir este filme no Brasil.</p>
    );
  }

  return (
    <div className="flex flex-col gap-4">
      {grupos.map(({ chave, titulo }) => (
        <Provedores key={chave} titulo={titulo} provedores={dados[chave]} />
      ))}
      <a
        href={dados.link}
        target="_blank"
        rel="noopener noreferrer"
        className="text-primary inline-flex w-fit items-center gap-1 text-sm underline-offset-4 hover:underline"
      >
        Ver todas as opções <ExternalLink className="size-3.5" aria-hidden="true" />
      </a>
      <p className="text-muted-foreground text-xs">
        Dados de onde assistir fornecidos por JustWatch.
      </p>
    </div>
  );
}

"use client";

import { Play } from "lucide-react";
import Image from "next/image";
import { useState } from "react";

/** Miniatura do YouTube; o player (sem cookies) só é carregado depois do clique. */
export function Trailer({ chave, titulo }: { chave: string; titulo: string }) {
  const [tocando, setTocando] = useState(false);

  return (
    <div className="bg-muted relative aspect-video w-full max-w-3xl overflow-hidden rounded-xl">
      {tocando ? (
        <iframe
          src={`https://www.youtube-nocookie.com/embed/${chave}?autoplay=1`}
          title={`Trailer de ${titulo}`}
          allow="autoplay; encrypted-media; picture-in-picture"
          allowFullScreen
          className="absolute inset-0 size-full"
        />
      ) : (
        <button
          type="button"
          onClick={() => setTocando(true)}
          className="group focus-visible:ring-ring/50 absolute inset-0 outline-none focus-visible:ring-3"
        >
          <Image
            src={`https://i.ytimg.com/vi/${chave}/hqdefault.jpg`}
            alt=""
            fill
            sizes="(min-width: 768px) 768px, 100vw"
            className="object-cover opacity-80 transition-opacity group-hover:opacity-100"
          />
          <span className="bg-primary text-primary-foreground absolute top-1/2 left-1/2 flex -translate-x-1/2 -translate-y-1/2 items-center gap-2 rounded-full px-5 py-3 font-medium shadow-lg">
            <Play className="size-5 fill-current" aria-hidden="true" />
            Assistir trailer
          </span>
        </button>
      )}
    </div>
  );
}

import Image from "next/image";

import { urlImagem } from "@/lib/tmdb/imagens";
import type { MembroElenco } from "@/lib/tmdb/tipos";

function iniciais(nome: string): string {
  const partes = nome.trim().split(/\s+/);
  return ((partes[0]?.[0] ?? "") + (partes.length > 1 ? (partes.at(-1)?.[0] ?? "") : ""))
    .toUpperCase();
}

export function Elenco({ pessoas }: { pessoas: MembroElenco[] }) {
  return (
    <ul className="flex gap-4 overflow-x-auto pb-2 [scrollbar-width:thin]">
      {pessoas.map((pessoa) => {
        const foto = urlImagem(pessoa.fotoPath, "w185");
        return (
          <li key={`${pessoa.nome}-${pessoa.personagem}`} className="flex w-28 shrink-0 flex-col gap-2">
            <div className="bg-muted relative aspect-[2/3] overflow-hidden rounded-lg">
              {foto ? (
                <Image src={foto} alt="" fill sizes="112px" className="object-cover" />
              ) : (
                <span
                  aria-hidden="true"
                  className="text-muted-foreground flex h-full items-center justify-center text-xl font-semibold"
                >
                  {iniciais(pessoa.nome)}
                </span>
              )}
            </div>
            <div>
              <p className="text-sm font-medium">{pessoa.nome}</p>
              {pessoa.personagem && (
                <p className="text-muted-foreground text-xs">{pessoa.personagem}</p>
              )}
            </div>
          </li>
        );
      })}
    </ul>
  );
}

