ed(D+"tipos.ts",[
 ["import type { Duracao, Frequencia } from \"@/features/preferencias/opcoes\";","import type { Duracao, Frequencia } from \"@/features/preferencias/opcoes\";\nimport type { Reacao } from \"@/features/reacoes/opcoes\";"],
 ["export type AvaliacaoMotor = {","export type ReacaoMotor = {"],
 ["  nota: 1 | 2 | 3 | 4 | 5;\n  /** Gêneros do filme avaliado, para o bônus de afinidade. */","  reacao: Reacao;\n  /** Gêneros do filme, para o bônus de afinidade. */"],
 ["  avaliacoes?: AvaliacaoMotor[];","  /** Reações do usuário (\"Não é pra mim\", \"Gostei\", \"Amei\"). */\n  reacoes?: ReacaoMotor[];"],
]);
ed(D+"planejar.ts",[
 ["AvaliacaoMotor","ReacaoMotor"],
 ["/** Avaliações de 4★ e 5★ que viram fonte de parecidos: as mais altas, até 3. */\nexport function origensDeParecidos(avaliacoes: ReacaoMotor[] = []): ReacaoMotor[] {\n  return avaliacoes\n    .filter((avaliacao) => avaliacao.nota >= 4)\n    .sort((a, b) => b.nota - a.nota)","const PRIORIDADE = { amei: 0, gostei: 1 } as const;\n\n/** Reações \"Amei\" e \"Gostei\" que viram fonte de parecidos: \"Amei\" primeiro, até 3. */\nexport function origensDeParecidos(reacoes: ReacaoMotor[] = []): ReacaoMotor[] {\n  return reacoes\n    .filter((r): r is ReacaoMotor & { reacao: keyof typeof PRIORIDADE } => r.reacao !== \"nao-gostei\")\n    .sort((a, b) => PRIORIDADE[a.reacao] - PRIORIDADE[b.reacao])"],
 ["export function planejar({ preferencias, avaliacoes }: EntradaMotor","export function planejar({ preferencias, reacoes }: EntradaMotor"],
 ["origensDeParecidos(avaliacoes)","origensDeParecidos(reacoes)"],
]);
ed(D+"ranquear.ts",[
 ["import type { AvaliacaoMotor, Gerador } from \"@/features/recomendacao/tipos\";","import type { Reacao } from \"@/features/reacoes/opcoes\";\nimport type { Gerador, ReacaoMotor } from \"@/features/recomendacao/tipos\";"],
 ["const PESO_POR_ESTRELA: Record<AvaliacaoMotor[\"nota\"], number> = {\n  5: 0.1,\n  4: 0.05,\n  3: 0,\n  2: -0.05,\n  1: -0.1,\n};","const PESO_POR_REACAO: Record<Reacao, number> = {\n  amei: 0.1,\n  gostei: 0.05,\n  \"nao-gostei\": -0.1,\n};"],
 ["/** Soma, por gênero, o peso das estrelas dadas a filmes daquele gênero. */\nexport function bonusPorGenero(avaliacoes: AvaliacaoMotor[] = []): Map<number, number> {","/** Soma, por gênero, o peso das reações dadas a filmes daquele gênero. */\nexport function bonusPorGenero(reacoes: ReacaoMotor[] = []): Map<number, number> {"],
 ["  for (const { nota, generos } of avaliacoes) {","  for (const { reacao, generos } of reacoes) {"],
 ["PESO_POR_ESTRELA[nota]","PESO_POR_REACAO[reacao]"],
]);
ed(D+"parecidos.ts",[
 ["AvaliacaoMotor","ReacaoMotor"],
 ["const PESO_ORIGEM: Partial<Record<ReacaoMotor[\"nota\"], number>> = { 5: 1, 4: 0.6 };","const PESO_ORIGEM: Partial<Record<ReacaoMotor[\"reacao\"], number>> = { amei: 1, gostei: 0.6 };"],
 ["PESO_ORIGEM[origem.nota]","PESO_ORIGEM[origem.reacao]"],
 ["Junta as recomendações do TMDB de cada filme bem avaliado.","Junta as recomendações do TMDB de cada filme marcado com \"Amei\" ou \"Gostei\"."],
]);
ed(D+"motivo.ts",[
 ["import type { AvaliacaoMotor } from \"@/features/recomendacao/tipos\";","import { VERBO_REACAO } from \"@/features/reacoes/opcoes\";\nimport type { ReacaoMotor } from \"@/features/recomendacao/tipos\";"],
 ["export function motivoParecido(origem: AvaliacaoMotor): string {\n  return `Parecido com ${origem.titulo}, que você deu ${origem.nota}★`;","/** \"Parecido com X, que você amou\". */\nexport function motivoParecido(origem: ReacaoMotor): string {\n  const verbo = origem.reacao === \"nao-gostei\" ? null : VERBO_REACAO[origem.reacao];\n  return verbo ? `Parecido com ${origem.titulo}, ${verbo.motivo}` : `Parecido com ${origem.titulo}`;\n}\n\n/** \"Porque você amou X\" / \"Porque você gostou de X\". */\nexport function tituloParecidos(origem: ReacaoMotor): string {\n  const verbo = origem.reacao === \"nao-gostei\" ? null : VERBO_REACAO[origem.reacao];\n  return verbo ? `${verbo.titulo} ${origem.titulo}` : `Parecidos com ${origem.titulo}`;"],
]);
ed(D+"gerar.ts",[
 ["import { motivoParecido, motivoPorGeneros } from \"@/features/recomendacao/motivo\";","import { motivoParecido, motivoPorGeneros, tituloParecidos } from \"@/features/recomendacao/motivo\";"],
 ["const { preferencias, avaliacoes = [] } = entrada;","const { preferencias, reacoes = [] } = entrada;"],
 ["// Já avaliados contam como vistos: não voltam como recomendação.","// Filmes com qualquer reação já foram vistos: não voltam como recomendação."],
 ["...avaliacoes.map((a) => a.tmdbId)","...reacoes.map((r) => r.tmdbId)"],
 ["bonusPorGenero(avaliacoes)","bonusPorGenero(reacoes)"],
 ["titulo: `Porque você deu ${origem.nota}★ para ${origem.titulo}`,","titulo: tituloParecidos(origem),"],
]);
