describe("RLS de reacoes", () => {
  let a: Awaited<ReturnType<typeof criarUsuario>>;
  let b: Awaited<ReturnType<typeof criarUsuario>>;

  beforeAll(async () => {
    a = await criarUsuario("Usuária A");
    b = await criarUsuario("Usuário B");
    const { error } = await b.cliente.from("reacoes").insert(linha(b.id, 550, "amei"));
    if (error) throw error;
  });

  it("o usuário grava, troca e apaga a própria reação", async () => {
    expect((await a.cliente.from("reacoes").upsert(linha(a.id, 13, "gostei"))).error).toBeNull();
    expect((await a.cliente.from("reacoes").upsert(linha(a.id, 13, "amei"))).error).toBeNull();

    const { data } = await a.cliente.from("reacoes").select("tmdb_id, reacao");
    expect(data).toEqual([{ tmdb_id: 13, reacao: "amei" }]);

    await a.cliente.from("reacoes").delete().eq("tmdb_id", 13);
    expect((await a.cliente.from("reacoes").select("tmdb_id")).data).toEqual([]);
  });

  it("o usuário não lê, não altera e não apaga as reações de outro", async () => {
    const leitura = await a.cliente.from("reacoes").select("tmdb_id").eq("usuario_id", b.id);
    expect(leitura.data).toEqual([]);

    const alteracao = await a.cliente
      .from("reacoes")
      .update({ reacao: "nao-gostei" })
      .eq("usuario_id", b.id)
      .select();
    expect(alteracao.data).toEqual([]);

    const exclusao = await a.cliente.from("reacoes").delete().eq("usuario_id", b.id).select();
    expect(exclusao.data).toEqual([]);

    const { data } = await b.cliente.from("reacoes").select("reacao").single();
    expect(data?.reacao).toBe("amei");
  });

  it("o usuário não insere reação em nome de outro", async () => {
    const { error } = await a.cliente.from("reacoes").insert(linha(b.id, 99, "gostei"));
    expect(error?.code).toBe("42501");
  });

  it("o banco recusa reação fora do enum e tmdb_id 0", async () => {
    const invalida = await a.cliente
      .from("reacoes")
      .insert({ ...linha(a.id, 77, "gostei"), reacao: "odiei" as "gostei" });
    expect(invalida.error?.code).toBe("22P02");

    const idZero = await a.cliente.from("reacoes").insert(linha(a.id, 0, "gostei"));
    expect(idZero.error?.code).toBe("23514");
  });
});

import { expect, test, type Page } from "@playwright/test";

import { emailAleatorio } from "../support/supabase-local";
import { cadastrar, concluirOnboarding } from "./helpers";

/** Abre o primeiro filme de "Escolhidos para você" e devolve o ID. */
async function abrirPrimeiroFilme(page: Page) {
  const card = page
    .getByRole("main")
    .getByRole("region", { name: "Escolhidos para você" })
    .getByRole("link")
    .first();
  const id = (await card.getAttribute("href"))?.split("/").at(-1) ?? "";
  await card.click();
  await expect(page).toHaveURL(`/filme/${id}`);
  return id;
}

const botao = (page: Page, nome: string) =>
  page.getByRole("group", { name: "O que achou?" }).getByRole("button", { name: nome });

test("Amei fica marcado, cria a seção de parecidos e some ao desfazer", async ({ page }) => {
  await cadastrar(page, "Nina Prado", emailAleatorio("e2e"));
  await concluirOnboarding(page);
  const id = await abrirPrimeiroFilme(page);

  await botao(page, "Amei").click();
  await expect(botao(page, "Amei")).toHaveAttribute("aria-pressed", "true");
  await page.reload();
  await expect(botao(page, "Amei")).toHaveAttribute("aria-pressed", "true");

  await page.goto("/dashboard");
  const main = page.getByRole("main");
  const secao = main.getByRole("region", { name: `Porque você amou Filme ${id}` });
  await expect(secao.getByRole("listitem").first()).toBeVisible();
  await expect(main.locator(`a[href="/filme/${id}"]`)).toHaveCount(0);

  await page.goto(`/filme/${id}`);
  await botao(page, "Amei").click();
  await expect(botao(page, "Amei")).toHaveAttribute("aria-pressed", "false");
  await page.reload();
  for (const nome of ["Não é pra mim", "Gostei", "Amei"]) {
    await expect(botao(page, nome)).toHaveAttribute("aria-pressed", "false");
  }

  await page.goto("/dashboard");
  await expect(page.getByRole("region", { name: "Escolhidos para você" })).toBeVisible();
  await expect(page.getByRole("region", { name: `Porque você amou Filme ${id}` })).toHaveCount(0);
});

test("trocar de Gostei para Não é pra mim deixa só a nova marcada", async ({ page }) => {
  await cadastrar(page, "Otto Reis", emailAleatorio("e2e"));
  await concluirOnboarding(page);
  await abrirPrimeiroFilme(page);

  await botao(page, "Gostei").click();
  await expect(botao(page, "Gostei")).toHaveAttribute("aria-pressed", "true");
  await botao(page, "Não é pra mim").click();
  await expect(botao(page, "Não é pra mim")).toHaveAttribute("aria-pressed", "true");

  await page.reload();
  await expect(botao(page, "Não é pra mim")).toHaveAttribute("aria-pressed", "true");
  await expect(botao(page, "Gostei")).toHaveAttribute("aria-pressed", "false");
  await expect(botao(page, "Amei")).toHaveAttribute("aria-pressed", "false");
});

