import { listaSchema } from "@/features/listas/schema";

vi.mock("@/features/listas/actions", () => ({ alternarLista: vi.fn(async () => ({})) }));

function item(tmdbId: number, sobrescrever: Partial<ItemLista> = {}): ItemLista {
  return {
    tmdbId,
    status: "assistido",
    titulo: `Filme ${tmdbId}`,
    posterPath: null,
    ano: 2020,
    reacao: null,
    ...sobrescrever,
