import type { Database } from "@/lib/supabase/database.types";

export type StatusLista = Database["public"]["Enums"]["status_lista"];

export const STATUS_LISTA = ["quero_assistir", "assistido"] as const satisfies StatusLista[];

export const ROTULOS_STATUS: Record<StatusLista, string> = {
  quero_assistir: "Quero assistir",
  assistido: "Já assisti",
};

export type Aba = "quero" | "assistidos";

export const STATUS_DA_ABA: Record<Aba, StatusLista> = {
  quero: "quero_assistir",
  assistidos: "assistido",
};

import type { Aba } from "@/features/listas/opcoes";

/** Lê `?aba=` da URL; qualquer valor diferente de "assistidos" abre "Quero assistir". */
export function lerAba(valor: string | string[] | undefined): Aba {
  return valor === "assistidos" ? "assistidos" : "quero";
}

import { z } from "zod";

import { STATUS_LISTA } from "@/features/listas/opcoes";
import { tmdbIdSchema } from "@/features/reacoes/schema";

export const listaSchema = z.object({
  tmdbId: tmdbIdSchema,
  status: z.enum(STATUS_LISTA),
});

import "server-only";

import { cache } from "react";

import type { StatusLista } from "@/features/listas/opcoes";
import type { Reacao } from "@/features/reacoes/opcoes";
import { createClient } from "@/lib/supabase/server";

export type ItemLista = {
  tmdbId: number;
  status: StatusLista;
  titulo: string;
  posterPath: string | null;
  ano: number | null;
  /** Reação dada ao filme, se houver (spec `reacoes`). */
  reacao: Reacao | null;
};

/** Itens das duas listas do usuário logado, do mais recente para o mais antigo. */
export const obterItensLista = cache(async (): Promise<ItemLista[]> => {
  const supabase = await createClient();
  const [itens, reacoes] = await Promise.all([
    supabase
      .from("lista_itens")
      .select("tmdb_id, status, titulo, poster_path, ano")
      .order("adicionado_em", { ascending: false }),
    supabase.from("reacoes").select("tmdb_id, reacao"),
  ]);

  if (itens.error) {
    console.error("[listas] falha ao ler:", itens.error.code, itens.error.message);
    throw new Error("Não foi possível carregar suas listas.");
  }
  const reacaoPorFilme = new Map((reacoes.data ?? []).map((r) => [r.tmdb_id, r.reacao]));

  return itens.data.map((linha) => ({
    tmdbId: linha.tmdb_id,
    status: linha.status,
    titulo: linha.titulo,
    posterPath: linha.poster_path,
    ano: linha.ano,
    reacao: reacaoPorFilme.get(linha.tmdb_id) ?? null,
  }));
});

/** IDs dos filmes nas duas listas, para o motor não recomendá-los. */
export async function idsNasListas(): Promise<number[]> {
  const supabase = await createClient();
  const { data, error } = await supabase.from("lista_itens").select("tmdb_id");
  if (error) {
    console.error("[listas] falha ao ler IDs:", error.code, error.message);
    return [];
  }
  return data.map((linha) => linha.tmdb_id);
}

/** Lista em que o filme está, ou `null`. */
export async function obterStatusLista(tmdbId: number): Promise<StatusLista | null> {
  const supabase = await createClient();
  const { data } = await supabase
    .from("lista_itens")
    .select("status")
    .eq("tmdb_id", tmdbId)
    .maybeSingle();
  return data?.status ?? null;
}

"use server";

import { revalidatePath } from "next/cache";

import { listaSchema } from "@/features/listas/schema";
import { createClient } from "@/lib/supabase/server";
import { obterFilme } from "@/lib/tmdb/filmes";

export type EstadoLista = { mensagem?: string };

const ERRO_GENERICO = "Não foi possível atualizar sua lista agora. Tente de novo.";

/**
 * Põe o filme na lista pedida; se ele já estava nela, tira (clicar de novo desfaz).
 * Os dados do filme vêm do TMDB no servidor, não do navegador.
 */
export async function alternarLista(
  _anterior: EstadoLista,
  formData: FormData,
): Promise<EstadoLista> {
  const resultado = listaSchema.safeParse({
    tmdbId: Number(formData.get("tmdbId")),
    status: formData.get("status"),
  });
  if (!resultado.success) return { mensagem: ERRO_GENERICO };
  const { tmdbId, status } = resultado.data;

  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return { mensagem: "Sua sessão expirou. Entre de novo." };

  const { data: atual } = await supabase
    .from("lista_itens")
    .select("status")
    .eq("tmdb_id", tmdbId)
    .maybeSingle();

  if (atual?.status === status) {
    const { error } = await supabase.from("lista_itens").delete().eq("tmdb_id", tmdbId);
    if (error) {
      console.error("[listas] falha ao remover:", error.code, error.message);
      return { mensagem: ERRO_GENERICO };
    }
  } else {
    let filme;
    try {
      filme = await obterFilme(tmdbId);
    } catch {
      return { mensagem: ERRO_GENERICO };
    }
    if (!filme) return { mensagem: "Filme não encontrado." };

    const { error } = await supabase.from("lista_itens").upsert({
      usuario_id: user.id,
      tmdb_id: tmdbId,
      status,
      titulo: filme.titulo,
      poster_path: filme.posterPath,
      ano: filme.ano,
      generos: filme.generos.map((genero) => genero.id),
      // Ao entrar ou trocar de lista, o filme vai para o topo da aba.
      adicionado_em: new Date().toISOString(),
    });
    if (error) {
      console.error("[listas] falha ao salvar:", error.code, error.message);
      return { mensagem: ERRO_GENERICO };
    }
  }

  revalidatePath(`/filme/${tmdbId}`);
  revalidatePath("/listas");
  revalidatePath("/dashboard");
  return {};
}

"use client";

import { cn } from "cn";
import { Bookmark, Check, type LucideIcon } from "lucide-react";
import { useActionState, useState } from "react";

import { alternarLista } from "@/features/listas/actions";
import { ROTULOS_STATUS, STATUS_LISTA, type StatusLista } from "@/features/listas/opcoes";

const ICONES: Record<StatusLista, LucideIcon> = {
  quero_assistir: Bookmark,
  assistido: Check,
};

/** "Quero assistir" e "Já assisti"; mesmo padrão dos botões de reação. */
export function BotoesLista({ tmdbId, atual }: { tmdbId: number; atual: StatusLista | null }) {
  const [estado, formAction, enviando] = useActionState(alternarLista, {});
  // Enquanto a ação roda, mostra o resultado esperado; depois, vale o que veio do servidor.
  const [palpite, setPalpite] = useState<StatusLista | null>(atual);
  const exibido = enviando ? palpite : atual;

  return (
    <div className="flex flex-col gap-2">
      <div role="group" aria-label="Minhas listas" className="flex flex-wrap gap-2">
        {STATUS_LISTA.map((status) => {
          const Icone = ICONES[status];
          const marcado = exibido === status;
          return (
            <form
              key={status}
              action={formAction}
              onSubmit={() => setPalpite(atual === status ? null : status)}
            >
              <input type="hidden" name="tmdbId" value={tmdbId} />
              <input type="hidden" name="status" value={status} />
              <button
                type="submit"
                aria-pressed={marcado}
                disabled={enviando}
                className={cn(
                  "border-border bg-background/60 inline-flex items-center gap-2 rounded-lg border px-4 py-2 text-sm transition-colors outline-none",
                  "hover:bg-muted focus-visible:ring-ring/50 focus-visible:ring-3 disabled:opacity-70",
                  marcado && "border-foreground bg-foreground text-background hover:bg-foreground/80",
                )}
              >
                <Icone
                  className={cn("size-4", marcado && status === "quero_assistir" && "fill-current")}
                />
                {ROTULOS_STATUS[status]}
              </button>
            </form>
          );
        })}
      </div>
      {estado.mensagem && (
        <p role="alert" className="text-destructive text-sm">
          {estado.mensagem}
        </p>
      )}
    </div>
  );
}

