import { beforeAll, describe, expect, it } from "vitest";

import { criarUsuario } from "../../support/supabase-local";

const item = (usuarioId: string, tmdbId: number, status: "quero_assistir" | "assistido") => ({
  usuario_id: usuarioId,
  tmdb_id: tmdbId,
  status,
  titulo: `Filme ${tmdbId}`,
  poster_path: null,
  ano: 2020,
  generos: [18],
});

describe("RLS de lista_itens", () => {
  let a: Awaited<ReturnType<typeof criarUsuario>>;
  let b: Awaited<ReturnType<typeof criarUsuario>>;

  beforeAll(async () => {
    a = await criarUsuario("Usuária A");
    b = await criarUsuario("Usuário B");
    const { error } = await b.cliente.from("lista_itens").insert(item(b.id, 550, "assistido"));
    if (error) throw error;
  });

  it("o usuário adiciona, troca de lista e remove o próprio item", async () => {
    const lista = a.cliente.from("lista_itens");
    expect((await lista.upsert(item(a.id, 13, "quero_assistir"))).error).toBeNull();
    expect((await lista.upsert(item(a.id, 13, "assistido"))).error).toBeNull();

    const { data } = await a.cliente.from("lista_itens").select("tmdb_id, status");
    expect(data).toEqual([{ tmdb_id: 13, status: "assistido" }]);

    await a.cliente.from("lista_itens").delete().eq("tmdb_id", 13);
    expect((await a.cliente.from("lista_itens").select("tmdb_id")).data).toEqual([]);
  });

  it("o usuário não lê, não altera e não apaga os itens de outro", async () => {
    const leitura = await a.cliente.from("lista_itens").select("tmdb_id").eq("usuario_id", b.id);
    expect(leitura.data).toEqual([]);

    const alteracao = await a.cliente
      .from("lista_itens")
      .update({ status: "quero_assistir" })
      .eq("usuario_id", b.id)
      .select();
    expect(alteracao.data).toEqual([]);

    const exclusao = await a.cliente.from("lista_itens").delete().eq("usuario_id", b.id).select();
    expect(exclusao.data).toEqual([]);

    const { data } = await b.cliente.from("lista_itens").select("status").single();
    expect(data?.status).toBe("assistido");
  });

  it("o usuário não insere item em nome de outro", async () => {
    const { error } = await a.cliente.from("lista_itens").insert(item(b.id, 99, "assistido"));
    expect(error?.code).toBe("42501");
  });

  it("o banco recusa status fora do enum e tmdb_id 0", async () => {
    const invalido = await a.cliente
      .from("lista_itens")
      .insert({ ...item(a.id, 77, "assistido"), status: "favorito" as "assistido" });
    expect(invalido.error?.code).toBe("22P02");

    const idZero = await a.cliente.from("lista_itens").insert(item(a.id, 0, "assistido"));
    expect(idZero.error?.code).toBe("23514");
  });
});

import { expect, test, type Page } from "@playwright/test";

import { emailAleatorio } from "../support/supabase-local";
import { cadastrar, concluirOnboarding } from "./helpers";

async function abrirPrimeiroFilme(page: Page) {
  const card = page
    .getByRole("main")
    .getByRole("region", { name: "Escolhidos para você" })
    .getByRole("link")
    .first();
  const id = (await card.getAttribute("href"))?.split("/").at(-1) ?? "";
  await card.click();
  await expect(page).toHaveURL(`/filme/${id}`);
  return id;
}

/** Clica num botão de um grupo e espera a Server Action terminar. */
async function clicar(page: Page, grupo: string, nome: string, marcado: "true" | "false") {
  const botao = page.getByRole("group", { name: grupo }).getByRole("button", { name: nome });
  await botao.click();
  await expect(botao).toBeEnabled();
  await expect(botao).toHaveAttribute("aria-pressed", marcado);
}

test("Quero assistir, Já assisti e remover, refletidos em /listas e no dashboard", async ({
  page,
}) => {
  await cadastrar(page, "Paula Neri", emailAleatorio("e2e"));
  await concluirOnboarding(page);
  const id = await abrirPrimeiroFilme(page);
  const cartao = (p: Page) => p.getByRole("main").locator(`a[href="/filme/${id}"]`);

  await clicar(page, "Minhas listas", "Quero assistir", "true");
  await page.getByRole("banner").getByRole("link", { name: "Minhas listas" }).click();
  await expect(page).toHaveURL("/listas");
  await expect(page.getByRole("link", { name: "Quero assistir (1)" })).toHaveAttribute(
    "aria-current",
    "page",
  );
  await expect(cartao(page)).toBeVisible();

  await page.goto(`/filme/${id}`);
  await clicar(page, "O que achou?", "Amei", "true");
  await clicar(page, "Minhas listas", "Já assisti", "true");
  await expect(
    page.getByRole("group", { name: "Minhas listas" }).getByRole("button", { name: "Quero assistir" }),
  ).toHaveAttribute("aria-pressed", "false");

  await page.goto("/listas?aba=assistidos");
  await expect(page.getByRole("link", { name: "Já assisti (1)" })).toHaveAttribute(
    "aria-current",
    "page",
  );
  await expect(page.getByRole("link", { name: "Quero assistir (0)" })).toBeVisible();
  await expect(cartao(page)).toBeVisible();
  await expect(page.getByRole("main").getByText("Amei")).toBeVisible();

  await page.goto("/dashboard");
  await expect(page.getByRole("region", { name: "Escolhidos para você" })).toBeVisible();
  await expect(cartao(page)).toHaveCount(0);

  await page.goto(`/filme/${id}`);
  await clicar(page, "Minhas listas", "Já assisti", "false");
  await page.goto("/listas?aba=assistidos");
  await expect(page.getByText(/Nada por aqui ainda/)).toBeVisible();
});

test("sem sessão, /listas exige login", async ({ page }) => {
  await page.goto("/listas");
  await expect(page).toHaveURL("/login?next=%2Flistas");
});

