import Link from "next/link";

import { buttonVariants } from "@/components/ui/button";

const MAX_PAGINAS_TMDB = 500;

function href(texto: string, pagina: number) {
  return `/busca?${new URLSearchParams({ q: texto, pagina: String(pagina) })}`;
}

export function Paginacao({
  texto,
  pagina,
  totalPaginas,
}: {
  texto: string;
  pagina: number;
  totalPaginas: number;
}) {
  const total = Math.min(totalPaginas, MAX_PAGINAS_TMDB);
  if (total <= 1) return null;

  return (
    <nav aria-label="Paginação" className="flex items-center justify-center gap-4 py-4">
      {pagina > 1 && (
        <Link href={href(texto, pagina - 1)} className={buttonVariants({ variant: "outline" })}>
          Anterior
        </Link>
      )}
      <span className="text-muted-foreground text-sm">
        Página {pagina} de {total}
      </span>
      {pagina < total && (
        <Link href={href(texto, pagina + 1)} className={buttonVariants({ variant: "outline" })}>
          Próxima
        </Link>
      )}
    </nav>
  );
}

