import { Paginacao } from "@/features/busca/components/paginacao";
import { MIN_TEXTO } from "@/features/busca/parametros";
import { CartaoFilme } from "@/features/dashboard/components/cartao-filme";
import type { FilmeResumo, Pagina } from "@/lib/tmdb/tipos";

const numeroPtBr = new Intl.NumberFormat("pt-BR");

type Props = {
  texto: string;
  /** `null` quando não houve busca (texto curto demais). */
  resultado: Pagina<FilmeResumo> | null;
};

export function ResultadosBusca({ texto, resultado }: Props) {
  if (texto.length < MIN_TEXTO || !resultado) {
    return <p className="text-muted-foreground">Digite o nome de um filme para começar.</p>;
  }

  if (resultado.itens.length === 0) {
    return <p className="text-muted-foreground">Nenhum filme encontrado para “{texto}”.</p>;
  }

  const total = resultado.totalResultados;
  return (
    <div className="flex flex-col gap-6">
      <p className="text-muted-foreground">
        {`${numeroPtBr.format(total)} ${total === 1 ? "resultado" : "resultados"} para “${texto}”`}
      </p>
      <ul className="grid grid-cols-[repeat(auto-fill,minmax(10rem,1fr))] gap-6">
        {resultado.itens.map((filme) => (
          <li key={filme.id}>
            <CartaoFilme filme={filme} />
          </li>
        ))}
      </ul>
      <Paginacao texto={texto} pagina={resultado.pagina} totalPaginas={resultado.totalPaginas} />
    </div>
  );
}

