import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";

import { Paginacao } from "@/features/busca/components/paginacao";
import { ResultadosBusca } from "@/features/busca/components/resultados-busca";
import { lerBusca } from "@/features/busca/parametros";
import type { FilmeResumo, Pagina } from "@/lib/tmdb/tipos";

function filme(id: number): FilmeResumo {
  return {
    id,
    titulo: `Matrix ${id}`,
    tituloOriginal: `Matrix ${id}`,
    sinopse: "",
    posterPath: null,
    backdropPath: null,
    generos: [878],
    ano: 1999,
    nota: 8.2,
    votos: 100,
    popularidade: 10,
  };
}

const pagina = (itens: FilmeResumo[], totalResultados: number, totalPaginas = 1): Pagina<FilmeResumo> => ({
  itens,
  pagina: 1,
  totalPaginas,
  totalResultados,
});

describe("lerBusca", () => {
  it("normaliza o texto", () => {
    expect(lerBusca({ q: "  clube   da luta " }).texto).toBe("clube da luta");
    expect(lerBusca({ q: "a".repeat(150) }).texto).toHaveLength(100);
    expect(lerBusca({}).texto).toBe("");
    expect(lerBusca({ q: ["a", "b"] }).texto).toBe("");
  });

  it("lê a página entre 1 e 500", () => {
    expect(lerBusca({ pagina: "2" }).pagina).toBe(2);
    for (const valor of ["0", "-1", "abc", "501", undefined]) {
      expect(lerBusca({ pagina: valor }).pagina).toBe(1);
    }
  });
});

describe("ResultadosBusca", () => {
  it("pede um texto quando a busca tem menos de 2 caracteres", () => {
    render(<ResultadosBusca texto="a" resultado={null} />);
    expect(screen.getByText("Digite o nome de um filme para começar.")).toBeInTheDocument();
  });

  it("mostra a contagem e os cards", () => {
    render(
      <ResultadosBusca texto="matrix" resultado={pagina([filme(1), filme(2)], 1234, 1)} />,
    );
    expect(screen.getByText("1.234 resultados para “matrix”")).toBeInTheDocument();
    expect(screen.getAllByRole("listitem")).toHaveLength(2);
    expect(screen.getByRole("link", { name: "Matrix 1 (1999)" })).toHaveAttribute(
      "href",
      "/filme/1",
    );
  });

  it("usa o singular com 1 resultado", () => {
    render(<ResultadosBusca texto="matrix" resultado={pagina([filme(1)], 1)} />);
    expect(screen.getByText("1 resultado para “matrix”")).toBeInTheDocument();
  });

  it("avisa quando não há resultados", () => {
    render(<ResultadosBusca texto="nada" resultado={pagina([], 0, 0)} />);
    expect(screen.getByText("Nenhum filme encontrado para “nada”.")).toBeInTheDocument();
  });
});

describe("Paginacao", () => {
  it("no meio, tem Anterior e Próxima mantendo o texto", () => {
    render(<Paginacao texto="matrix" pagina={2} totalPaginas={3} />);
    expect(screen.getByText("Página 2 de 3")).toBeInTheDocument();
    expect(screen.getByRole("link", { name: "Anterior" })).toHaveAttribute(
      "href",
      "/busca?q=matrix&pagina=1",
    );
    expect(screen.getByRole("link", { name: "Próxima" })).toHaveAttribute(
      "href",
      "/busca?q=matrix&pagina=3",
    );
  });

  it("na primeira página não há Anterior; na última não há Próxima", () => {
    const { rerender } = render(<Paginacao texto="matrix" pagina={1} totalPaginas={3} />);
    expect(screen.queryByRole("link", { name: "Anterior" })).not.toBeInTheDocument();
    rerender(<Paginacao texto="matrix" pagina={3} totalPaginas={3} />);
    expect(screen.queryByRole("link", { name: "Próxima" })).not.toBeInTheDocument();
  });

  it("não aparece com uma página só", () => {
    const { container } = render(<Paginacao texto="matrix" pagina={1} totalPaginas={1} />);
    expect(container).toBeEmptyDOMElement();
  });
});

const MAX_TEXTO = 100;
const MAX_PAGINA = 500;
export const MIN_TEXTO = 2;

type Parametros = Record<string, string | string[] | undefined>;

/** Lê `q` e `pagina` da URL da busca, já normalizados. */
export function lerBusca(parametros: Parametros): { texto: string; pagina: number } {
  const q = parametros.q;
  const texto = typeof q === "string" ? q.trim().replace(/\s+/g, " ").slice(0, MAX_TEXTO) : "";

  const bruto = parametros.pagina;
  const numero = typeof bruto === "string" && /^\d+$/.test(bruto) ? Number(bruto) : 1;
  const pagina = numero >= 1 && numero <= MAX_PAGINA ? numero : 1;

  return { texto, pagina };
}

export function urlBusca(texto: string, pagina = 1): string {
  const parametros = new URLSearchParams({ q: texto });
  if (pagina > 1) parametros.set("pagina", String(pagina));
  return `/busca?${parametros}`;
}

import Link from "next/link";

import { buttonVariants } from "@/components/ui/button";

const MAX_PAGINAS_TMDB = 500;

function href(texto: string, pagina: number) {
  return `/busca?${new URLSearchParams({ q: texto, pagina: String(pagina) })}`;
}

export function Paginacao({
  texto,
  pagina,
  totalPaginas,
}: {
  texto: string;
  pagina: number;
  totalPaginas: number;
}) {
  const total = Math.min(totalPaginas, MAX_PAGINAS_TMDB);
  if (total <= 1) return null;

  return (
    <nav aria-label="Paginação" className="flex items-center justify-center gap-4 py-4">
      {pagina > 1 && (
        <Link href={href(texto, pagina - 1)} className={buttonVariants({ variant: "outline" })}>
          Anterior
        </Link>
      )}
      <span className="text-muted-foreground text-sm">
        Página {pagina} de {total}
      </span>
      {pagina < total && (
        <Link href={href(texto, pagina + 1)} className={buttonVariants({ variant: "outline" })}>
          Próxima
        </Link>
      )}
    </nav>
  );
}

