"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";

import { nomeSchema } from "@/features/auth/schema";
import { preferenciasSchema } from "@/features/preferencias/schema";
import { createClient } from "@/lib/supabase/server";

export type EstadoPerfil = {
  ok?: boolean;
  /** Erro do campo nome (formulário de dados). */
  erroNome?: string;
  /** Erro geral do formulário. */
  mensagem?: string;
};

const ERRO_GENERICO = "Não foi possível salvar agora. Tente de novo.";

async function usuarioLogado() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  return { supabase, user };
}

export async function atualizarNome(
  _anterior: EstadoPerfil,
  formData: FormData,
): Promise<EstadoPerfil> {
  const resultado = z.object({ nome: nomeSchema }).safeParse({ nome: formData.get("nome") ?? "" });
  if (!resultado.success) return { erroNome: resultado.error.issues[0]?.message };

  const { supabase, user } = await usuarioLogado();
  if (!user) return { mensagem: "Sua sessão expirou. Entre de novo." };

  const { error } = await supabase
    .from("perfis")
    .update({ nome: resultado.data.nome })
    .eq("id", user.id);
  if (error) {
    console.error("[perfil] falha ao salvar nome:", error.code, error.message);
    return { mensagem: ERRO_GENERICO };
  }

  revalidatePath("/", "layout");
  return { ok: true };
}

export async function atualizarPreferencias(
  _anterior: EstadoPerfil,
  formData: FormData,
): Promise<EstadoPerfil> {
  const resultado = preferenciasSchema.safeParse({
    generos: formData.getAll("generos").map(Number),
    duracao: formData.get("duracao"),
    frequencia: formData.get("frequencia"),
  });
  if (!resultado.success) return { mensagem: resultado.error.issues[0]?.message ?? ERRO_GENERICO };

  const { supabase, user } = await usuarioLogado();
  if (!user) return { mensagem: "Sua sessão expirou. Entre de novo." };

  const { error } = await supabase
    .from("preferencias")
    .update(resultado.data)
    .eq("usuario_id", user.id);
  if (error) {
    console.error("[perfil] falha ao salvar preferências:", error.code, error.message);
    return { mensagem: ERRO_GENERICO };
  }

  revalidatePath("/", "layout");
  return { ok: true };
}

"use client";

import { useActionState, useState, type FormEvent } from "react";

import { Button } from "@/components/ui/button";
import { Campo } from "@/features/auth/components/campo";
import { MensagemErro } from "@/features/auth/components/mensagem-erro";
import { nomeSchema } from "@/features/auth/schema";
import { atualizarNome } from "@/features/perfil/actions";
import { MensagemSucesso } from "@/features/perfil/components/mensagem-sucesso";

export function FormularioNome({ nome, email }: { nome: string; email: string }) {
  const [estado, formAction, salvando] = useActionState(atualizarNome, {});
  const [erroCliente, setErroCliente] = useState<string | null>(null);

  function aoEnviar(evento: FormEvent<HTMLFormElement>) {
    const resultado = nomeSchema.safeParse(new FormData(evento.currentTarget).get("nome") ?? "");
    if (resultado.success) {
      setErroCliente(null);
      return;
    }
    evento.preventDefault();
    setErroCliente(resultado.error.issues[0]?.message ?? null);
  }

  return (
    <form action={formAction} onSubmit={aoEnviar} noValidate className="flex max-w-md flex-col gap-4">
      <MensagemErro mensagem={estado.mensagem} />
      <Campo
        name="nome"
        rotulo="Nome"
        autoComplete="name"
        defaultValue={nome}
        erro={erroCliente ?? estado.erroNome}
      />
      <div className="flex flex-col gap-1">
        <p className="text-sm font-medium">Email</p>
        <p className="text-muted-foreground text-sm">{email}</p>
        <p className="text-muted-foreground text-xs">Não é possível alterar o email.</p>
      </div>
      <div className="flex items-center gap-4">
        <Button type="submit" size="lg" className="h-10 px-5" disabled={salvando}>
          {salvando ? "Salvando…" : "Salvar nome"}
        </Button>
        {estado.ok && !erroCliente && !salvando && <MensagemSucesso />}
      </div>
    </form>
  );
}

import { CircleCheck } from "lucide-react";

export function MensagemSucesso() {
  return (
    <p role="status" className="inline-flex items-center gap-1.5 text-sm text-emerald-400">
      <CircleCheck className="size-4" aria-hidden="true" />
      Alterações salvas.
    </p>
  );
}

"use client";

import { useActionState, useState } from "react";

import { Button } from "@/components/ui/button";
import { MensagemErro } from "@/features/auth/components/mensagem-erro";
import { atualizarPreferencias } from "@/features/perfil/actions";
import { MensagemSucesso } from "@/features/perfil/components/mensagem-sucesso";
import { alternar, ChipsGeneros } from "@/features/preferencias/components/chips-generos";
import { GrupoOpcoes } from "@/features/preferencias/components/grupo-opcoes";
import {
  DURACOES,
  FREQUENCIAS,
  ROTULOS_DURACAO,
  ROTULOS_FREQUENCIA,
} from "@/features/preferencias/opcoes";
import type { PreferenciasInput } from "@/features/preferencias/schema";

/** As mesmas perguntas do onboarding numa página só, já preenchidas. */
export function FormularioPreferencias({ atuais }: { atuais: PreferenciasInput }) {
  const [estado, formAction, salvando] = useActionState(atualizarPreferencias, {});
  const [generos, setGeneros] = useState(atuais.generos);
  const [duracao, setDuracao] = useState(atuais.duracao);
  const [frequencia, setFrequencia] = useState(atuais.frequencia);

  return (
    <form action={formAction} className="flex flex-col gap-8">
      <MensagemErro mensagem={estado.mensagem} />
      <ChipsGeneros
        titulo="Gêneros favoritos"
        selecionados={generos}
        aoAlternar={(id) => setGeneros((lista) => alternar(lista, id))}
      />
      <div className="grid gap-8 md:grid-cols-2">
        <GrupoOpcoes
          nome="duracao"
          rotulo="Duração preferida"
          opcoes={DURACOES}
          rotulos={ROTULOS_DURACAO}
          valor={duracao}
          aoMudar={setDuracao}
        />
        <GrupoOpcoes
          nome="frequencia"
          rotulo="Com que frequência você assiste filmes?"
          opcoes={FREQUENCIAS}
          rotulos={ROTULOS_FREQUENCIA}
          valor={frequencia}
          aoMudar={setFrequencia}
        />
      </div>

      {generos.map((id) => (
        <input key={id} type="hidden" name="generos" value={id} />
      ))}
      <input type="hidden" name="duracao" value={duracao} />
      <input type="hidden" name="frequencia" value={frequencia} />

      <div className="flex items-center gap-4">
        <Button
          type="submit"
          size="lg"
          className="h-10 px-5"
          disabled={salvando || generos.length === 0}
        >
          {salvando ? "Salvando…" : "Salvar preferências"}
        </Button>
        {estado.ok && !salvando && <MensagemSucesso />}
      </div>
    </form>
  );
}

