import fs from "node:fs";
const [entrada, saida] = process.argv.slice(2);
const AVISO = "[imagem removida antes de publicar: print do painel da Vercel com parte do TMDB_READ_TOKEN]";
let removidas = 0;
const alvos = new Set();
const linhas = fs.readFileSync(entrada, "utf8").split("\n");
// 1ª passada: acha as imagens das mensagens que falam do deploy na Vercel.
function textoDe(conteudo) {
  return Array.isArray(conteudo) ? conteudo.filter((c) => c?.type === "text").map((c) => c.text).join(" ") : String(conteudo ?? "");
}
for (const l of linhas) {
  if (!l) continue;
  const o = JSON.parse(l);
  const c = o.message?.content;
  if (Array.isArray(c) && /fazendo deploy/.test(textoDe(c))) {
    for (const b of c) if (b?.type === "image") alvos.add(b.source?.data?.slice(0, 200));
  }
}
// 2ª passada: troca toda ocorrência dessas imagens, em qualquer lugar da linha.
function limpar(v) {
  if (Array.isArray(v)) return v.map(limpar);
  if (v && typeof v === "object") {
    if (v.type === "image" && alvos.has(v.source?.data?.slice(0, 200))) { removidas++; return { type: "text", text: AVISO }; }
    return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, limpar(x)]));
  }
  return v;
}
const out = linhas.map((l) => (l ? JSON.stringify(limpar(JSON.parse(l))) : l));
fs.writeFileSync(saida, out.join("\n"));
console.log(`alvos=${alvos.size} removidas=${removidas}`);
EOF
