import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";

import { GloboSurpresa } from "@/features/surpresa/components/globo-surpresa";
import { anguloPara } from "@/features/surpresa/angulo";
import { montarGlobo, type ApiGlobo, type FilmeGlobo } from "@/features/surpresa/montar";
import { TmdbErro } from "@/lib/tmdb/cliente";
import type { FilmeResumo, FiltrosDescoberta } from "@/lib/tmdb/tipos";

function filme(id: number, sobrescrever: Partial<FilmeResumo> = {}): FilmeResumo {
  return {
    id,
    titulo: `Filme ${id}`,
    tituloOriginal: `Filme ${id}`,
    sinopse: `Sinopse ${id}`,
    posterPath: `/p${id}.jpg`,
    backdropPath: null,
    generos: [18],
    ano: 2020,
    nota: 7.5,
    votos: 1000,
    popularidade: 10,
    ...sobrescrever,
  };
}

const preferencias = { generos: [18, 28], duracao: "media", frequencia: "semanal" } as const;

/** TMDB falso: a consulta com semGeneros é a "fora da bolha". */
function apiFalsa(opcoes: { falharBolha?: boolean } = {}) {
  const chamadas: FiltrosDescoberta[] = [];
  const api: ApiGlobo = {
    descobrirFilmes: vi.fn(async (filtros: FiltrosDescoberta = {}) => {
      chamadas.push(filtros);
      const bolha = Boolean(filtros.semGeneros);
      if (bolha && opcoes.falharBolha) throw new TmdbErro("TMDB respondeu 503", 503);
      const base = bolha ? 9000 : 1000;
      const generoBolha = filtros.generos?.[0] ?? 37;
      return {
        pagina: 1,
        totalPaginas: 5,
        totalResultados: 100,
        itens: Array.from({ length: 10 }, (_, i) =>
          filme(base + i, {
            generos: bolha ? [generoBolha] : [18],
            posterPath: i === 9 ? null : `/p${base + i}.jpg`,
          }),
        ),
      };
    }),
  };
  return { api, chamadas };
}

describe("montarGlobo", () => {
  it("faz uma consulta do gosto e uma fora da bolha, com os filtros certos", async () => {
    const { api, chamadas } = apiFalsa();
    await montarGlobo({ preferencias: { ...preferencias, generos: [18, 28] }, api, aleatorio: () => 0 });

    const gosto = chamadas.find((f) => !f.semGeneros);
    const bolha = chamadas.find((f) => f.semGeneros);
    expect(gosto).toMatchObject({
      generos: [18, 28],
      duracaoMin: 90,
      duracaoMax: 120,
      votosMin: 300,
      notaMin: 6.5,
      ordem: "popularidade",
    });
    expect(gosto?.pagina).toBeGreaterThanOrEqual(6);
    expect(gosto?.pagina).toBeLessThanOrEqual(10);

    expect(bolha?.generos).toHaveLength(3);
    for (const genero of bolha?.generos ?? []) expect([18, 28]).not.toContain(genero);
    expect(bolha).toMatchObject({ semGeneros: [18, 28], notaMin: 6.5, votosMin: 500 });
  });

  it("devolve até 6 de cada origem, sem excluídos, sem pôster ausente e sem repetidos", async () => {
    const { api } = apiFalsa();
    const globo = await montarGlobo({
      preferencias: { ...preferencias, generos: [18, 28] },
      excluir: [1000, 1001, 9000],
      api,
      aleatorio: Math.random,
    });

    const ids = globo.map((f) => f.id);
    expect(globo.filter((f) => f.origem === "gosto")).toHaveLength(6);
    expect(globo.filter((f) => f.origem === "bolha")).toHaveLength(6);
    expect(new Set(ids).size).toBe(ids.length);
    for (const id of [1000, 1001, 9000, 1009, 9009]) expect(ids).not.toContain(id);
  });

  it("explica a origem no motivo", async () => {
    const { api, chamadas } = apiFalsa();
    const globo = await montarGlobo({
      preferencias: { ...preferencias, generos: [18, 28] },
      api,
      aleatorio: () => 0,
    });
    const generoBolha = chamadas.find((f) => f.semGeneros)?.generos?.[0];
    const nome = (await import("@/features/preferencias/generos")).GENEROS.find(
      (g) => g.id === generoBolha,
    )?.nome;

    expect(globo.find((f) => f.origem === "gosto")?.motivo).toBe("Porque você curte Drama");
    expect(globo.find((f) => f.origem === "bolha")?.motivo).toBe(
      `Fora da sua bolha: ${nome} bem avaliado`,
    );
  });

  it("se a bolha falha, usa só o gosto; com menos de 3 filmes, devolve vazio", async () => {
    const erro = vi.spyOn(console, "error").mockImplementation(() => {});
    const { api } = apiFalsa({ falharBolha: true });
    const globo = await montarGlobo({ preferencias: { ...preferencias }, api, aleatorio: () => 0 });
    expect(globo.length).toBe(6);
    expect(globo.every((f) => f.origem === "gosto")).toBe(true);

    const quase = await montarGlobo({
      preferencias: { ...preferencias },
      excluir: Array.from({ length: 8 }, (_, i) => 1000 + i),
      api,
      aleatorio: () => 0,
    });
    expect(quase).toEqual([]);
    erro.mockRestore();
  });
});

describe("anguloPara", () => {
  it.each([
    [0, 0, 12],
    [-37, 5, 12],
    [-1234.5, 11, 12],
    [0, 2, 7],
  ])("a partir de %d, deixa o item %d de %d de frente, com 3 voltas", (atual, indice, total) => {
    const alvo = anguloPara(atual, indice, total);
    const frente = (((alvo + (indice * 360) / total) % 360) + 360) % 360;
    expect(Math.min(frente, 360 - frente)).toBeCloseTo(0);
    expect(alvo).toBeLessThanOrEqual(atual - 3 * 360);
    expect(alvo).toBeGreaterThan(atual - 4 * 360 - 1e-9);
  });
});

describe("GloboSurpresa", () => {
  const filmes: FilmeGlobo[] = [1, 2, 3].map((id) => ({
    id,
    titulo: `Filme ${id}`,
    ano: 2020,
    nota: 7.5,
    sinopse: `Sinopse ${id}`,
    posterPath: `/p${id}.jpg`,
    motivo: "Porque você curte Drama",
    origem: "gosto",
  }));

  it("sem animação, abre o pop-up do filme sorteado, sorteia outro e fecha", async () => {
    const usuario = userEvent.setup();
    render(<GloboSurpresa filmes={filmes} />);

    expect(screen.getByRole("heading", { name: "Não sabe o que ver?" })).toBeInTheDocument();
    await usuario.click(screen.getByRole("button", { name: "Me surpreenda" }));

    const dialogo = await screen.findByRole("dialog");
    const titulo = dialogo.querySelector("h2")?.textContent ?? "";
    expect(titulo).toMatch(/^Filme [123]$/);
    const id = titulo.split(" ")[1];
    expect(screen.getByRole("link", { name: "Ver detalhes" })).toHaveAttribute("href", `/filme/${id}`);
    expect(screen.getByText("Porque você curte Drama")).toBeInTheDocument();

    await usuario.click(screen.getByRole("button", { name: "Sortear outro" }));
    expect(await screen.findByRole("dialog")).toBeInTheDocument();

    await usuario.click(screen.getByRole("button", { name: "Fechar" }));
    expect(screen.queryByRole("dialog")).not.toBeInTheDocument();
  });
});

/**
 * Ângulo final do anel (rotateY, em graus) para que o item `indice` de `total`
 * pare de frente, girando `voltas` voltas completas a partir de `atual`.
 * O item `i` fica em `i × 360/total`; ele está de frente quando
 * `angulo + i × 360/total` é múltiplo de 360.
 */
export function anguloPara(atual: number, indice: number, total: number, voltas = 3): number {
  const passo = 360 / total;
  const inicio = atual - voltas * 360;
  const sobra = (((inicio + indice * passo) % 360) + 360) % 360;
  return inicio - sobra;
}

import { GENEROS } from "@/features/preferencias/generos";
import type { PreferenciasInput } from "@/features/preferencias/schema";
import { motivoPorGeneros } from "@/features/recomendacao/motivo";
import { filtrosDeDuracao, PERFIS } from "@/features/recomendacao/perfil";
import type { ApiFilmes } from "@/lib/tmdb/filmes";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

export type ApiGlobo = Pick<ApiFilmes, "descobrirFilmes">;

export type FilmeGlobo = Pick<FilmeResumo, "id" | "titulo" | "ano" | "nota" | "sinopse"> & {
  posterPath: string;
  motivo: string;
  origem: "gosto" | "bolha";
};

type Entrada = {
  preferencias: PreferenciasInput;
  excluir?: number[];
  api: ApiGlobo;
  /** Gerador em [0, 1); injetável para os testes. */
  aleatorio?: () => number;
};

const POR_ORIGEM = 6;
const GENEROS_BOLHA = 3;
const MINIMO_NO_GLOBO = 3;
const BOLHA = { notaMin: 6.5, votosMin: 500, paginaMax: 5 };

function inteiroEntre(aleatorio: () => number, min: number, max: number) {
  return min + Math.floor(aleatorio() * (max - min + 1));
}

/** Fisher–Yates com o gerador recebido. */
function embaralhar<T>(lista: T[], aleatorio: () => number): T[] {
  const copia = [...lista];
  for (let i = copia.length - 1; i > 0; i--) {
    const j = Math.floor(aleatorio() * (i + 1));
    [copia[i], copia[j]] = [copia[j]!, copia[i]!];
  }
  return copia;
}

async function consultar(api: ApiGlobo, filtros: Parameters<ApiGlobo["descobrirFilmes"]>[0]) {
  try {
    return (await api.descobrirFilmes(filtros)).itens;
  } catch (erro) {
    console.error("[surpresa] consulta falhou:", erro);
    return [];
  }
}

/**
 * Até 6 filmes do gosto da pessoa (de páginas que os carrosséis não usam) e até 6
 * de gêneros que ela não escolheu, bem avaliados. Lista vazia se sobrarem menos de 3.
 */
export async function montarGlobo({
  preferencias,
  excluir = [],
  api,
  aleatorio = Math.random,
}: Entrada): Promise<FilmeGlobo[]> {
  const perfil = PERFIS[preferencias.frequencia];
  const favoritos = preferencias.generos;
  const generosBolha = embaralhar(
    GENEROS.map(({ id }) => id).filter((id) => !favoritos.includes(id)),
    aleatorio,
  ).slice(0, GENEROS_BOLHA);

  const [doGosto, daBolha] = await Promise.all([
    consultar(api, {
      generos: favoritos,
      ...filtrosDeDuracao(preferencias.duracao),
      votosMin: perfil.votosMin,
      notaMin: perfil.notaMin,
      ordem: "popularidade",
      pagina: inteiroEntre(aleatorio, perfil.paginaMax + 1, perfil.paginaMax + 5),
    }),
    consultar(api, {
      generos: generosBolha,
      semGeneros: favoritos,
      notaMin: BOLHA.notaMin,
      votosMin: BOLHA.votosMin,
      ordem: "popularidade",
      pagina: inteiroEntre(aleatorio, 1, BOLHA.paginaMax),
    }),
  ]);

  const vistos = new Set(excluir);
  function escolher(filmes: FilmeResumo[]) {
    const validos = filmes.filter((filme) => {
      if (!filme.posterPath || vistos.has(filme.id)) return false;
      vistos.add(filme.id);
      return true;
    });
    return embaralhar(validos, aleatorio).slice(0, POR_ORIGEM);
  }

  const nomeDoGenero = (filme: FilmeResumo) =>
    GENEROS.find(({ id }) => filme.generos.includes(id) && generosBolha.includes(id))?.nome ??
    "um gênero novo";

  const globo: FilmeGlobo[] = [
    ...escolher(doGosto).map((filme) => ({
      ...resumo(filme),
      motivo: motivoPorGeneros(filme.generos, favoritos),
      origem: "gosto" as const,
    })),
    ...escolher(daBolha).map((filme) => ({
      ...resumo(filme),
      motivo: `Fora da sua bolha: ${nomeDoGenero(filme)} bem avaliado`,
      origem: "bolha" as const,
    })),
  ];

  return globo.length < MINIMO_NO_GLOBO ? [] : embaralhar(globo, aleatorio);
}

function resumo(filme: FilmeResumo) {
  return {
    id: filme.id,
    titulo: filme.titulo,
    ano: filme.ano,
    nota: filme.nota,
    sinopse: filme.sinopse,
    posterPath: filme.posterPath ?? "",
  };
}

"use client";

import { Shuffle, X } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useCallback, useEffect, useRef, useState } from "react";

import { Button, buttonVariants } from "@/components/ui/button";
import { anguloPara } from "@/features/surpresa/angulo";
import type { FilmeGlobo } from "@/features/surpresa/montar";
import { urlImagem } from "@/lib/tmdb/imagens";

const DURACAO_GIRO_MS = 2600;
const GRAUS_POR_SEGUNDO_REPOUSO = 9; // uma volta a cada 40 s

function prefereMenosMovimento() {
  return (
    typeof window.matchMedia !== "function" ||
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

/** Globo de pôsteres que gira e para num filme sorteado, abrindo um pop-up com ele. */
export function GloboSurpresa({ filmes }: { filmes: FilmeGlobo[] }) {
  const anel = useRef<HTMLDivElement>(null);
  const dialogo = useRef<HTMLDialogElement>(null);
  const angulo = useRef(0);
  const girando = useRef(false);
  const [sorteando, setSorteando] = useState(false);
  const [escolhido, setEscolhido] = useState<FilmeGlobo | null>(null);

  const total = filmes.length;
  const passo = 360 / total;
  // Raio que deixa os pôsteres (≈ 8 rem) lado a lado no círculo.
  const raio = Math.round(70 / Math.tan(Math.PI / total));

  const aplicar = useCallback((graus: number, transicao: string) => {
    angulo.current = graus;
    if (!anel.current) return;
    anel.current.style.transition = transicao;
    anel.current.style.transform = `translateZ(${-raio}px) rotateY(${graus}deg)`;
  }, [raio]);

  // Giro lento em repouso.
  useEffect(() => {
    aplicar(angulo.current, "none");
    if (prefereMenosMovimento()) return;
    let quadro = 0;
    let anterior = performance.now();
    const passar = (agora: number) => {
      if (!girando.current) {
        aplicar(angulo.current - ((agora - anterior) / 1000) * GRAUS_POR_SEGUNDO_REPOUSO, "none");
      }
      anterior = agora;
      quadro = requestAnimationFrame(passar);
    };
    quadro = requestAnimationFrame(passar);
    return () => cancelAnimationFrame(quadro);
  }, [aplicar]);

  const abrir = useCallback((filme: FilmeGlobo) => {
    setEscolhido(filme);
    girando.current = false;
    setSorteando(false);
  }, []);

  // O pop-up abre depois que o React renderiza o filme escolhido.
  useEffect(() => {
    const elemento = dialogo.current;
    if (!escolhido || !elemento || elemento.open) return;
    if (typeof elemento.showModal === "function") elemento.showModal();
    else elemento.setAttribute("open", "");
  }, [escolhido]);

  function fechar() {
    const elemento = dialogo.current;
    if (elemento?.open) {
      if (typeof elemento.close === "function") elemento.close();
      else elemento.removeAttribute("open");
    }
    setEscolhido(null);
  }

  function sortear() {
    if (girando.current) return;
    fechar();
    const indice = Math.floor(Math.random() * total);
    const filme = filmes[indice]!;

    if (prefereMenosMovimento() || !anel.current) {
      aplicar(-indice * passo, "none");
      abrir(filme);
      return;
    }

    girando.current = true;
    setSorteando(true);
    const elemento = anel.current;
    let concluido = false;
    const concluir = () => {
      if (concluido) return;
      concluido = true;
      elemento.removeEventListener("transitionend", concluir);
      abrir(filme);
    };
    elemento.addEventListener("transitionend", concluir);
    window.setTimeout(concluir, DURACAO_GIRO_MS + 400);
    aplicar(
      anguloPara(angulo.current, indice, total),
      `transform ${DURACAO_GIRO_MS}ms cubic-bezier(0.12, 0.7, 0.18, 1)`,
    );
  }

  return (
    <section
      aria-labelledby="titulo-surpresa"
      className="border-border/60 from-primary/10 via-background to-background flex flex-col items-center gap-6 overflow-hidden rounded-2xl border bg-gradient-to-b px-4 py-8"
    >
      <div className="text-center">
        <h2 id="titulo-surpresa" className="text-2xl font-bold tracking-tight">
          Não sabe o que ver?
        </h2>
        <p className="text-muted-foreground mt-1 text-sm">
          Gire o globo e deixe o Filme Certo escolher.
        </p>
      </div>

      <div
        aria-hidden="true"
        className="relative h-56 w-full [perspective:1100px] sm:h-64"
      >
        <div
          ref={anel}
          className="absolute top-1/2 left-1/2 h-48 w-32 -translate-x-1/2 -translate-y-1/2 [transform-style:preserve-3d] sm:h-56 sm:w-36"
        >
          {filmes.map((filme, i) => (
            <div
              key={filme.id}
              className="absolute inset-0 overflow-hidden rounded-lg shadow-xl [backface-visibility:hidden]"
              style={{ transform: `rotateY(${i * passo}deg) translateZ(${raio}px)` }}
            >
              <Image
                src={urlImagem(filme.posterPath, "w185") ?? ""}
                alt=""
                fill
                sizes="144px"
                className="object-cover"
              />
            </div>
          ))}
        </div>
      </div>

      <Button size="lg" className="h-11 gap-2 px-6 text-base" onClick={sortear} disabled={sorteando}>
        <Shuffle className="size-5" aria-hidden="true" />
        {sorteando ? "Sorteando…" : "Me surpreenda"}
      </Button>

      <dialog
        ref={dialogo}
        aria-labelledby="titulo-sorteado"
        onClose={() => setEscolhido(null)}
        className="bg-card text-foreground border-border m-auto w-[min(92vw,40rem)] rounded-2xl border p-0 shadow-2xl backdrop:bg-black/70"
      >
        {escolhido && (
          <div className="relative flex flex-col gap-5 p-5 sm:flex-row sm:p-6">
            <button
              type="button"
              aria-label="Fechar"
              onClick={fechar}
              className="text-muted-foreground hover:text-foreground absolute top-3 right-3 rounded-full p-1"
            >
              <X className="size-5" aria-hidden="true" />
            </button>
            <div className="bg-muted relative mx-auto aspect-[2/3] w-36 shrink-0 overflow-hidden rounded-lg sm:mx-0 sm:w-44">
              <Image
                src={urlImagem(escolhido.posterPath, "w342") ?? ""}
                alt=""
                fill
                sizes="176px"
                className="object-cover"
              />
            </div>
            <div className="flex flex-col gap-3">
              <p className="text-primary text-xs font-semibold tracking-wide uppercase">
                Sua surpresa de hoje
              </p>
              <h2 id="titulo-sorteado" className="pr-6 text-2xl font-bold tracking-tight">
                {escolhido.titulo}
              </h2>
              <p className="text-muted-foreground text-sm">
                {[escolhido.ano, `★ ${escolhido.nota.toFixed(1)}`].filter(Boolean).join(" · ")}
              </p>
              {escolhido.sinopse && <p className="line-clamp-4 text-sm">{escolhido.sinopse}</p>}
              <p className="text-muted-foreground text-xs">{escolhido.motivo}</p>
              <div className="mt-auto flex flex-wrap gap-2 pt-2">
                <Link href={`/filme/${escolhido.id}`} className={buttonVariants({ size: "lg" })}>
                  Ver detalhes
                </Link>
                <Button variant="outline" size="lg" onClick={sortear}>
                  Sortear outro
                </Button>
              </div>
            </div>
          </div>
        )}
      </dialog>
    </section>
  );
}

