cat > tests/e2e/zz-debug.spec.ts <<'EOF'
import { test } from "@playwright/test";
import { emailAleatorio } from "../support/supabase-local";
import { cadastrar } from "./helpers";
test("debug", async ({ page }) => {
  const logs: string[] = [];
  page.on("console", (m) => { if (m.type() === "error") logs.push(`[console] ${m.text().slice(0, 300)}`); });
  page.on("pageerror", (e) => logs.push(`[pageerror] ${e.message.slice(0, 400)}`));
  page.on("response", (r) => { if (r.status() >= 500 || r.request().method() === "POST") logs.push(`[${r.status()}] ${r.request().method()} ${r.url().slice(0, 80)}`); });
  await cadastrar(page, "Debug", emailAleatorio("e2e"));
  await page.waitForURL("**/onboarding");
  const main = page.getByRole("main");
  await main.getByRole("button", { name: "Ação", exact: true }).click();
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("radio", { name: "Tanto faz" }).check();
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("radio", { name: "Toda semana" }).check();
  await main.getByRole("button", { name: "Concluir" }).click();
  await page.waitForTimeout(6000);
  logs.push("URL " + page.url());
  console.log(logs.join("\n"));
});
EOF
