12	
13	const DURACAO_GIRO_MS = 1800;
14	const VOLTAS_NO_GIRO = 3;
15	// Quem pede menos movimento ainda vê o giro do sorteio (iniciado por um clique), mais suave.
16	const VOLTAS_NO_GIRO_SUAVE = 1;
17	const GRAUS_POR_SEGUNDO_REPOUSO = 9; // uma volta a cada 40 s
18	
19	/** Sem matchMedia (ambiente de teste), não há como animar: o pop-up abre direto. */
20	function semAnimacao() {
21	  return typeof window.matchMedia !== "function";
22	}
23	
24	function prefereMenosMovimento() {
25	  return semAnimacao() || window.matchMedia("(prefers-reduced-motion: reduce)").matches;
26	}
27	
28	/** Globo de pôsteres que gira e para num filme sorteado, abrindo um pop-up com ele. */
29	export function GloboSurpresa({ filmes }: { filmes: FilmeGlobo[] }) {
30	  const anel = useRef<HTMLDivElement>(null);
31	  const dialogo = useRef<HTMLDialogElement>(null);
32	  const angulo = useRef(0);
33	  const girando = useRef(false);
34	  const [sorteando, setSorteando] = useState(false);
35	  const [escolhido, setEscolhido] = useState<FilmeGlobo | null>(null);
36	  // Conta os sorteios: o mesmo filme pode sair duas vezes seguidas e o pop-up precisa reabrir.
37	  const [sorteios, setSorteios] = useState(0);
38	
39	  const total = filmes.length;
40	  const passo = 360 / total;
41	  // Raio que deixa os pôsteres (≈ 8 rem) lado a lado no círculo.
42	  const raio = Math.round(70 / Math.tan(Math.PI / total));
43	
44	  const aplicar = useCallback(
45	    (graus: number, transicao: string) => {
46	      angulo.current = graus;
47	      if (!anel.current) return;
48	      anel.current.style.transition = transicao;
49	      anel.current.style.transform = `translateZ(${-raio}px) rotateY(${graus}deg)`;
50	    },
51	    [raio],
52	  );
53	
54	  // Giro lento em repouso.
55	  useEffect(() => {
56	    aplicar(angulo.current, "none");
57	    if (prefereMenosMovimento()) return;
58	    let quadro = 0;
59	    let anterior = performance.now();
60	    const passar = (agora: number) => {
61	      if (!girando.current) {
62	        aplicar(angulo.current - ((agora - anterior) / 1000) * GRAUS_POR_SEGUNDO_REPOUSO, "none");
63	      }
64	      anterior = agora;
65	      quadro = requestAnimationFrame(passar);
66	    };
67	    quadro = requestAnimationFrame(passar);
68	    return () => cancelAnimationFrame(quadro);
69	  }, [aplicar]);
70	
71	  const abrir = useCallback((filme: FilmeGlobo) => {
72	    setEscolhido(filme);
73	    setSorteios((n) => n + 1);
74	    girando.current = false;
75	    setSorteando(false);
76	  }, []);
77	
78	  // O pop-up abre depois que o React renderiza o filme escolhido.
79	  useEffect(() => {
80	    const elemento = dialogo.current;
81	    if (!escolhido || !elemento || elemento.open) return;
82	    if (typeof elemento.showModal === "function") elemento.showModal();
83	    else elemento.setAttribute("open", "");
84	  }, [escolhido, sorteios]);
85	
86	  function fechar() {
87	    const elemento = dialogo.current;
88	    if (elemento?.open) {
89	      if (typeof elemento.close === "function") elemento.close();
90	      else elemento.removeAttribute("open");
91	    }
92	    setEscolhido(null);
93	  }
94	
95	  function sortear() {
96	    if (girando.current) return;
97	    fechar();
98	    const indice = Math.floor(Math.random() * total);
99	    const filme = filmes[indice]!;
100	
101	    if (semAnimacao() || !anel.current) {
102	      aplicar(-indice * passo, "none");
103	      abrir(filme);
104	      return;
105	    }
106	
107	    girando.current = true;
108	    setSorteando(true);
109	    const elemento = anel.current;
110	    let concluido = false;
111	    const concluir = () => {
112	      if (concluido) return;
113	      concluido = true;
114	      elemento.removeEventListener("transitionend", concluir);
115	      abrir(filme);
116	    };
117	    elemento.addEventListener("transitionend", concluir);
118	    window.setTimeout(concluir, DURACAO_GIRO_MS + 400);
119	    aplicar(
120	      anguloPara(
121	        angulo.current,
122	        indice,
123	        total,
124	        prefereMenosMovimento() ? VOLTAS_NO_GIRO_SUAVE : VOLTAS_NO_GIRO,
125	      ),
126	      `transform ${DURACAO_GIRO_MS}ms cubic-bezier(0.12, 0.7, 0.18, 1)`,
127	    );
128	  }
129	
130	  return (
131	    <section
132	      aria-labelledby="titulo-surpresa"
133	      className="border-border/60 from-primary/10 via-background to-background flex flex-col items-center gap-6 overflow-hidden rounded-2xl border bg-gradient-to-b px-4 py-8"
