              </p>
              <h2 id="titulo-sorteado" className="pr-6 text-2xl font-bold tracking-tight">
                {escolhido.titulo}
              </h2>
              <p className="text-muted-foreground text-sm">
                {[escolhido.ano, `★ ${escolhido.nota.toFixed(1)}`].filter(Boolean).join(" · ")}
